window.FIX6={"adm-buet-preli-2022-23": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট প্রিলি ২০২২-২৩", "chapter": "Admission", "level": "বুয়েট প্রিলি", "minutes": 33, "qjson": "[{\"q\": \"দুটি \\\\(120\\\\ \\\\mathrm{Nm^{-1}}\\\\) স্প্রিং ধ্রুবকের স্প্রিং সমান্তরাল সমবায়ে যুক্ত করে, সেই জোটের সাথে \\\\(80\\\\ \\\\mathrm{Nm^{-1}}\\\\) ধ্রুবকের একটি স্প্রিং শ্রেণি সমবায়ে যুক্ত করে \\\\(10\\\\ \\\\mathrm{kg}\\\\) ভরের বস্তু সংযোগ দেওয়া হলো। সম্পূর্ণ সিস্টেমের পর্যায়কাল কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(1.55\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(2.56\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(3.56\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(4.50\\\\ \\\\mathrm{s}\\\\)\"], \"ans\": 1, \"why\": \"সমান্তরাল জোটের ধ্রুবক \\\\(120 + 120 = 240\\\\); শ্রেণিতে \\\\(k_{eq} = \\\\frac{240 \\\\times 80}{240 + 80} = 60\\\\ \\\\mathrm{Nm^{-1}}\\\\); \\\\(T = 2\\\\pi\\\\sqrt{\\\\frac{10}{60}} = 2.56\\\\ \\\\mathrm{s}\\\\)\"}, {\"q\": \"\\\\(3\\\\ \\\\mathrm{m}\\\\) ব্যাস ও \\\\(5\\\\ \\\\mathrm{m}\\\\) উচ্চতা বিশিষ্ট একটি সিলিন্ডারকে শোয়ানো অবস্থা থেকে খাড়া করতে কৃতকাজ কত? [সিলিন্ডারের ভর \\\\(= 5\\\\ \\\\mathrm{kg}\\\\)] [BUET Preli 22-23]\", \"opts\": [\"\\\\(40\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(49\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(98\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(147\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 1, \"why\": \"ভরকেন্দ্র ওঠে \\\\(\\\\frac{5}{2} - \\\\frac{3}{2} = 1\\\\ \\\\mathrm{m}\\\\); \\\\(W = mgh = 5 \\\\times 9.8 \\\\times 1 = 49\\\\ \\\\mathrm{J}\\\\)\"}, {\"q\": \"সরল ছন্দিত স্পন্দনে গতিশীল কোনো কণার \\\\(x = 2\\\\ \\\\mathrm{cm}\\\\) তে স্থিতিশক্তি গতিশক্তির \\\\(\\\\frac{1}{3}\\\\) গুণ হলে বিস্তার কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(3\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(4\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(6\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(8\\\\ \\\\mathrm{cm}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(E_p = \\\\frac{1}{3}E_k\\\\) → \\\\(x^2 = \\\\frac{A^2 - x^2}{3}\\\\) → \\\\(A^2 = 4x^2\\\\), অর্থাৎ \\\\(A = 2x = 4\\\\ \\\\mathrm{cm}\\\\)\"}, {\"q\": \"কোনো দণ্ডের উপাদানের ইয়ং এর গুণাঙ্ক \\\\(800\\\\ \\\\mathrm{GPa}\\\\)। দণ্ডের দৈর্ঘ্য \\\\(20\\\\%\\\\) বৃদ্ধিতে প্রযুক্ত পীড়ন \\\\(= ?\\\\) [BUET Preli 22-23]\", \"opts\": [\"\\\\(1.6 \\\\times 10^{10}\\\\ \\\\mathrm{Nm^{-2}}\\\\)\", \"\\\\(1.6 \\\\times 10^{11}\\\\ \\\\mathrm{Nm^{-2}}\\\\)\", \"\\\\(1.6 \\\\times 10^{12}\\\\ \\\\mathrm{Nm^{-2}}\\\\)\", \"\\\\(1.6 \\\\times 10^{13}\\\\ \\\\mathrm{Nm^{-2}}\\\\)\"], \"ans\": 1, \"why\": \"পীড়ন \\\\(= Y \\\\times\\\\) বিকৃতি \\\\(= 800 \\\\times 10^9 \\\\times 0.20 = 1.6 \\\\times 10^{11}\\\\ \\\\mathrm{Nm^{-2}}\\\\)\"}, {\"q\": \"মঙ্গলগ্রহের ভর ও ব্যাসার্ধ যথাক্রমে পৃথিবীর ভর ও ব্যাসার্ধের \\\\(16\\\\) গুণ এবং \\\\(49\\\\) গুণ। মঙ্গলগ্রহের মুক্তিবেগ কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(5.4\\\\ \\\\mathrm{kms^{-1}}\\\\)\", \"\\\\(6.4\\\\ \\\\mathrm{kms^{-1}}\\\\)\", \"\\\\(7.4\\\\ \\\\mathrm{kms^{-1}}\\\\)\", \"\\\\(8.4\\\\ \\\\mathrm{kms^{-1}}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(v \\\\propto \\\\sqrt{\\\\frac{M}{R}}\\\\); \\\\(v_m = \\\\sqrt{\\\\frac{16}{49}} \\\\times 11.2 = \\\\frac{4}{7} \\\\times 11.2 = 6.4\\\\ \\\\mathrm{kms^{-1}}\\\\)\"}, {\"q\": \"স্যাটেলাইটের গতিশক্তির সমীকরণ কোনটি? [BUET Preli 22-23]\", \"opts\": [\"\\\\(E_k = \\\\frac{GMm}{R+h}\\\\)\", \"\\\\(E_k = \\\\frac{GMm}{2(R+h)}\\\\)\", \"\\\\(E_k = \\\\frac{-GMm}{R+h}\\\\)\", \"\\\\(E_k = \\\\frac{-GMm}{2(R+h)}\\\\)\"], \"ans\": 1, \"why\": \"কক্ষপথে \\\\(\\\\frac{GMm}{(R+h)^2} = \\\\frac{mv^2}{R+h}\\\\) থেকে \\\\(E_k = \\\\frac{1}{2}mv^2 = \\\\frac{GMm}{2(R+h)}\\\\)\"}, {\"q\": \"\\\\(10\\\\ \\\\mathrm{m}\\\\) উচ্চতা থেকে \\\\(10\\\\ \\\\mathrm{kg}\\\\) ভরের একটি হাতুড়ি পেরেকে আঘাতপ্রাপ্ত হয়ে \\\\(5\\\\ \\\\mathrm{cm}\\\\) নিচে ঢুকে গেল। মাটির গড় বাধাদানকারী বল কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(19698\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(2000\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(19968\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(19869\\\\ \\\\mathrm{N}\\\\)\"], \"ans\": 0, \"why\": \"কাজ-শক্তি উপপাদ্যে \\\\(mg(h + x) = Fx\\\\); \\\\(F = \\\\frac{10 \\\\times 9.8 \\\\times (10 + 0.05)}{0.05} = 19698\\\\ \\\\mathrm{N}\\\\)\"}, {\"q\": \"\\\\(0.8c\\\\) বেগে চলমান রকেট থেকে মিটার স্কেলের দৈর্ঘ্য কত হবে? [BUET Preli 22-23]\", \"opts\": [\"\\\\(0.8\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(0.7\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(0.6\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(0.4\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 2, \"why\": \"দৈর্ঘ্য সংকোচনে \\\\(L = L_0\\\\sqrt{1 - \\\\frac{v^2}{c^2}} = \\\\sqrt{1 - 0.8^2} = 0.6\\\\ \\\\mathrm{m}\\\\)\"}, {\"q\": \"সমোষ্ণ প্রক্রিয়ায় কোনটি ধ্রুবক? [BUET Preli 22-23]\", \"opts\": [\"আয়তন\", \"চাপ\", \"তাপমাত্রা\", \"তাপ\"], \"ans\": 2, \"why\": \"সমোষ্ণ (আইসোথার্মাল) প্রক্রিয়ায় তাপমাত্রা ধ্রুবক থাকে; এসময় চাপ ও আয়তন বয়েলের সূত্রানুযায়ী পরস্পরের ব্যস্তানুপাতে বদলায়।\"}, {\"q\": \"একটি বর্তনীতে \\\\(10\\\\ \\\\mathrm{V}\\\\) ব্যাটারির সঙ্গে শ্রেণিতে \\\\(10\\\\ \\\\Omega\\\\) ও \\\\(5\\\\ \\\\Omega\\\\) রোধ যুক্ত আছে, এবং এর পর (\\\\(10\\\\ \\\\Omega\\\\) ও \\\\(10\\\\ \\\\Omega\\\\) রোধের শ্রেণি সমবায়ের সঙ্গে \\\\(20\\\\ \\\\Omega\\\\) রোধ সমান্তরালে) যুক্ত আছে। বর্তনীর মূল প্রবাহ (Current) কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(0.04\\\\ \\\\mathrm{A}\\\\)\", \"\\\\(4000\\\\ \\\\mathrm{mA}\\\\)\", \"\\\\(400\\\\ \\\\mathrm{mA}\\\\)\", \"ক ও গ\"], \"ans\": 2, \"why\": \"সমান্তরাল অংশ \\\\(= \\\\frac{20 \\\\times 20}{20+20} = 10\\\\ \\\\Omega\\\\); \\\\(R_{eq} = 10 + 5 + 10 = 25\\\\ \\\\Omega\\\\); \\\\(I = \\\\frac{V}{R_{eq}} = \\\\frac{10}{25} = 0.4\\\\ \\\\mathrm{A} = 400\\\\ \\\\mathrm{mA}\\\\)।\"}, {\"q\": \"গ্যালভানোমিটার ও শান্টের সঠিক সম্পর্ক কোনটি? [BUET Preli 22-23]\", \"opts\": [\"\\\\(S = \\\\frac{G}{n+1}\\\\)\", \"\\\\(S = \\\\frac{G}{n-1}\\\\)\", \"\\\\(G = \\\\frac{S}{n-1}\\\\)\", \"\\\\(G = \\\\frac{S}{n+L}\\\\)\"], \"ans\": 1, \"why\": \"পাল্লা n গুণ বাড়াতে প্রয়োজনীয় শান্ট \\\\(S = \\\\frac{G}{n-1}\\\\), যেখানে G গ্যালভানোমিটারের রোধ।\"}, {\"q\": \"কোনটির তরঙ্গদৈর্ঘ্য বেশি? [BUET Preli 22-23]\", \"opts\": [\"নীল\", \"হলুদ\", \"কমলা\", \"লাল\"], \"ans\": 3, \"why\": \"দৃশ্যমান বর্ণালীতে তরঙ্গদৈর্ঘ্যের ক্রম: লাল > কমলা > হলুদ > নীল; লাল আলোর তরঙ্গদৈর্ঘ্য সর্বাধিক (প্রায় \\\\(700\\\\ \\\\mathrm{nm}\\\\))।\"}, {\"q\": \"\\\\(\\\\sqrt{\\\\mu_0 \\\\varepsilon_0}\\\\) এর মাত্রা কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(MLT^{-1}\\\\)\", \"\\\\(ML^2T^{-1}\\\\)\", \"\\\\(T^{-1}L\\\\)\", \"\\\\(TL^{-1}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(c = \\\\frac{1}{\\\\sqrt{\\\\mu_0 \\\\varepsilon_0}}\\\\) ⇒ \\\\(\\\\sqrt{\\\\mu_0 \\\\varepsilon_0} = \\\\frac{1}{c}\\\\), অর্থাৎ বেগের মাত্রার বিপরীত: \\\\(TL^{-1}\\\\)।\"}, {\"q\": \"পয়েন্টিং ভেক্টরের সূত্র কোনটি? [BUET Preli 22-23]\", \"opts\": [\"\\\\(\\\\frac{1}{\\\\mu}(\\\\vec{B} \\\\times \\\\vec{H})\\\\)\", \"\\\\(\\\\frac{1}{\\\\mu}(\\\\vec{E} \\\\times \\\\vec{H})\\\\)\", \"\\\\((\\\\vec{E} \\\\times \\\\vec{H})\\\\)\", \"\\\\(\\\\frac{1}{\\\\mu}(\\\\vec{B} \\\\times \\\\vec{E})\\\\)\"], \"ans\": 2, \"why\": \"পয়েন্টিং ভেক্টর \\\\(\\\\vec{S} = \\\\vec{E} \\\\times \\\\vec{H}\\\\) — তাড়িতচুম্বকীয় তরঙ্গের শক্তি-প্রবাহের দিক ও তীব্রতা নির্দেশ করে।\"}, {\"q\": \"একটি বস্তুর জড়তার ভ্রামক \\\\(5\\\\ \\\\mathrm{kgm^2}\\\\) ও কৌণিক বেগ \\\\(65\\\\ \\\\mathrm{rads^{-1}}\\\\) হলে, ঘূর্ণন অক্ষের সাপেক্ষে এর কৌণিক (ঘূর্ণন) গতিশক্তি কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(11.5\\\\ \\\\mathrm{kJ}\\\\)\", \"\\\\(12.6\\\\ \\\\mathrm{kJ}\\\\)\", \"\\\\(10.6\\\\ \\\\mathrm{kJ}\\\\)\", \"\\\\(9.6\\\\ \\\\mathrm{kJ}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(E = \\\\frac{1}{2} I \\\\omega^2 = \\\\frac{1}{2} \\\\times 5 \\\\times (65)^2 = 10562.5\\\\ \\\\mathrm{J} \\\\approx 10.6\\\\ \\\\mathrm{kJ}\\\\)।\"}, {\"q\": \"একক চিড়ের ক্ষেত্রে, ১ম অন্ধকার ডোরার জন্য কৌণিক দূরত্ব কত? [তরঙ্গদৈর্ঘ্য \\\\(= 5600\\\\ \\\\text{Å}\\\\) এবং চিড়ের প্রস্থ \\\\(5\\\\ \\\\mathrm{mm}\\\\)] [BUET Preli 22-23]\", \"opts\": [\"\\\\(4.417 \\\\times 10^{-3}{}^{\\\\circ}\\\\)\", \"\\\\(5.417 \\\\times 10^{-3}{}^{\\\\circ}\\\\)\", \"\\\\(6.417 \\\\times 10^{-3}{}^{\\\\circ}\\\\)\", \"\\\\(7.417 \\\\times 10^{-3}{}^{\\\\circ}\\\\)\"], \"ans\": 2, \"why\": \"একক চিড়ের ১ম ন্যূনতমে \\\\(a \\\\sin\\\\theta = \\\\lambda\\\\) ⇒ \\\\(\\\\theta = \\\\sin^{-1}\\\\left(\\\\frac{5600 \\\\times 10^{-10}}{0.005}\\\\right) = 6.417 \\\\times 10^{-3}{}^{\\\\circ}\\\\)।\"}, {\"q\": \"কোনো বস্তুর গতিশক্তি, এর নিশ্চল শক্তির 3 গুণ হলে \\\\(m\\\\) ও \\\\(m_0\\\\) এর সম্পর্ক কোনটি? [BUET Preli 22-23]\", \"opts\": [\"\\\\(m = 4m_0\\\\)\", \"\\\\(m = 3m_0\\\\)\", \"\\\\(m = 2m_0\\\\)\", \"\\\\(m = m_0\\\\)\"], \"ans\": 0, \"why\": \"\\\\(E_k = (m - m_0)c^2 = 3m_0c^2\\\\) ⇒ \\\\(m - m_0 = 3m_0\\\\) ⇒ \\\\(m = 4m_0\\\\)।\"}, {\"q\": \"কোনো পদার্থের অর্ধায়ু 10 দিন হলে 75% ক্ষয় হতে কত সময় লাগে? [BUET Preli 22-23]\", \"opts\": [\"10 d\", \"15 d\", \"20 d\", \"30 d\"], \"ans\": 2, \"why\": \"75% ক্ষয় মানে 25% অবশিষ্ট \\\\(= \\\\left(\\\\frac{1}{2}\\\\right)^2\\\\), অর্থাৎ 2টি অর্ধায়ু অতিবাহিত: \\\\(2 \\\\times 10 = 20\\\\) দিন।\"}, {\"q\": \"কারেন্ট বিবর্ধক গুণক \\\\(\\\\alpha = ?\\\\) [BUET Preli 22-23]\", \"opts\": [\"\\\\(\\\\frac{I_C}{I_E}\\\\)\", \"\\\\(\\\\frac{I_C}{I_B}\\\\)\", \"\\\\(\\\\frac{I_E}{I_B}\\\\)\", \"কোনোটিই নয়\"], \"ans\": 0, \"why\": \"কমন-বেস বিন্যাসে \\\\(\\\\alpha = \\\\frac{I_C}{I_E}\\\\) (কমন-ইমিটার বিন্যাসে \\\\(\\\\beta = \\\\frac{I_C}{I_B}\\\\))।\"}, {\"q\": \"কমন বেস ট্রানজিস্টরের Collector current \\\\(47\\\\ \\\\mu\\\\mathrm{A}\\\\) হতে \\\\(96\\\\ \\\\mu\\\\mathrm{A}\\\\) এবং emitter current \\\\(100\\\\ \\\\mu\\\\mathrm{A}\\\\) হতে \\\\(150\\\\ \\\\mu\\\\mathrm{A}\\\\) হলো। Current Amplification factor = ? [BUET Preli 22-23]\", \"opts\": [\"0.98\", \"0.99\", \"0.49\", \"0.48\"], \"ans\": 0, \"why\": \"\\\\(\\\\alpha = \\\\frac{\\\\Delta I_C}{\\\\Delta I_E} = \\\\frac{96 - 47}{150 - 100} = \\\\frac{49}{50} = 0.98\\\\)।\"}, {\"q\": \"হ্রদের তলদেশে অবস্থানরত একটি বেলুনের আয়তন ভূ-পৃষ্ঠে ৮ গুণ হয়। হ্রদের গভীরতা কত? [বাতাসের চাপ \\\\(P_a = 1.013 \\\\times 10^5\\\\ \\\\mathrm{Pa}\\\\)] [BUET Preli 22-23]\", \"opts\": [\"\\\\(63\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(72\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(81\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(91\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 1, \"why\": \"বয়েলের সূত্রে \\\\((P_a + h\\\\rho g) V = P_a \\\\cdot 8V\\\\) ⇒ \\\\(h\\\\rho g = 7P_a\\\\) ⇒ \\\\(h = \\\\frac{7 \\\\times 1.013 \\\\times 10^5}{1000 \\\\times 9.8} = 72.36\\\\ \\\\mathrm{m} \\\\approx 72\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"X-অক্ষ থেকে \\\\(30^{\\\\circ}\\\\) কোণে একটি ভেক্টর \\\\(|\\\\vec{A}| = 2\\\\); Y-অক্ষ বরাবর \\\\(|\\\\vec{B}| = 3\\\\) হলে \\\\(|\\\\vec{A} - \\\\vec{B}| = ?\\\\) [BUET Preli 22-23]\", \"opts\": [\"2.628\", \"2.646\", \"3.6148\", \"1.5168\"], \"ans\": 1, \"why\": \"\\\\(\\\\vec{A} = 2\\\\cos30^{\\\\circ}\\\\hat{i} + 2\\\\sin30^{\\\\circ}\\\\hat{j} = \\\\sqrt{3}\\\\hat{i} + \\\\hat{j}\\\\), \\\\(\\\\vec{B} = 3\\\\hat{j}\\\\) ⇒ \\\\(\\\\vec{A} - \\\\vec{B} = \\\\sqrt{3}\\\\hat{i} - 2\\\\hat{j}\\\\), যার মান \\\\(\\\\sqrt{3 + 4} = \\\\sqrt{7} = 2.646\\\\)।\"}, {\"q\": \"\\\\(4\\\\ \\\\mathrm{kmh^{-1}}\\\\) বেগে প্রবাহমান স্রোতযুক্ত নদীতে কত কোণে নৌকা চালালে \\\\(5\\\\ \\\\mathrm{kmh^{-1}}\\\\) বেগে নৌকা চালাতে সক্ষম একজন মাঝি ঠিক অপর পাড়ে পৌঁছাতে পারবে? [BUET Preli 22-23]\", \"opts\": [\"\\\\(120^{\\\\circ}\\\\)\", \"\\\\(90^{\\\\circ}\\\\)\", \"\\\\(136.37^{\\\\circ}\\\\)\", \"\\\\(143.1301^{\\\\circ}\\\\)\"], \"ans\": 3, \"why\": \"ঠিক সোজা পাড়ি দিতে নৌকার বেগের স্রোত-বরাবর উপাংশ স্রোতকে বাতিল করবে: \\\\(v\\\\cos\\\\alpha + u = 0\\\\) ⇒ \\\\(\\\\alpha = \\\\cos^{-1}\\\\left(-\\\\frac{u}{v}\\\\right) = \\\\cos^{-1}\\\\left(-\\\\frac{4}{5}\\\\right) = 143.1301^{\\\\circ}\\\\)।\"}, {\"q\": \"একটি বাস তার ভ্রমণের শুরুতে অর্ধেক অংশ \\\\(15\\\\ \\\\mathrm{ms^{-2}}\\\\) ত্বরণে এবং অবশিষ্ট অংশে \\\\(5\\\\ \\\\mathrm{ms^{-2}}\\\\) মন্দনে চলে। পুরো পথ জুড়ে তার অতিক্রান্ত দূরত্ব \\\\(120\\\\ \\\\mathrm{m}\\\\) হলে, চলার সর্বোচ্চ বেগ কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(20\\\\sqrt{2}\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(30\\\\sqrt{2}\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(30\\\\sqrt{3}\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(20\\\\sqrt{3}\\\\ \\\\mathrm{ms^{-1}}\\\\)\"], \"ans\": 1, \"why\": \"প্রথম অর্ধেক \\\\(s_1 = 60\\\\ \\\\mathrm{m}\\\\): \\\\(v^2 = u^2 + 2as_1 = 0 + 2 \\\\times 15 \\\\times 60 = 1800\\\\) ⇒ \\\\(v = 30\\\\sqrt{2}\\\\ \\\\mathrm{ms^{-1}}\\\\); মাঝপথেই বেগ সর্বোচ্চ।\"}, {\"q\": \"একটি বলকে ভূমির সাথে \\\\(45^{\\\\circ}\\\\) কোণে নিক্ষেপ করা হলে x দূরত্বে একটি দেয়ালকে কোনোমতে অতিক্রম করে ও দেয়াল থেকে y দূরত্বে ভূমিতে পড়ে। দেয়ালের উচ্চতা কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(\\\\frac{y}{(x+y)x}\\\\)\", \"\\\\(\\\\frac{y}{(x+y)y}\\\\)\", \"\\\\(\\\\frac{xy}{x-y}\\\\)\", \"\\\\(\\\\frac{xy}{x+y}\\\\)\"], \"ans\": 3, \"why\": \"আনুভূমিক পাল্লা \\\\(R = x + y\\\\); x দূরত্বে প্রাসের উচ্চতা \\\\(H = x\\\\tan45^{\\\\circ}\\\\left(1 - \\\\frac{x}{R}\\\\right) = x \\\\cdot \\\\frac{y}{x+y} = \\\\frac{xy}{x+y}\\\\) — কোনোমতে অতিক্রম করায় এটাই দেয়ালের উচ্চতা।\"}, {\"q\": \"ভূমির সাথে \\\\(60^{\\\\circ}\\\\) কোণে \\\\(40\\\\ \\\\mathrm{ms^{-1}}\\\\) বেগে নিক্ষিপ্ত একটি বস্তুর ভূমি হতে সর্বোচ্চ উচ্চতা কত হবে? [\\\\(g = 10\\\\ \\\\mathrm{ms^{-2}}\\\\)] [BUET Preli 22-23]\", \"opts\": [\"30 m\", \"40 m\", \"60 m\", \"80 m\"], \"ans\": 2, \"why\": \"\\\\(H = \\\\frac{(u \\\\sin\\\\alpha)^2}{2g} = \\\\frac{(40 \\\\sin 60^{\\\\circ})^2}{2 \\\\times 10} = \\\\frac{1600 \\\\times \\\\frac{3}{4}}{20} = 60\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"ভূমির সঙ্গে \\\\(60^{\\\\circ}\\\\) কোণে আনত একটি প্রক্ষেপকের আনুভূমিক পাল্লা ও সর্বোচ্চ উচ্চতার অনুপাত কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(3 : 2\\\\)\", \"\\\\(\\\\sqrt{3} : 4\\\\)\", \"\\\\(4 : \\\\sqrt{3}\\\\)\", \"\\\\(4 : 3\\\\)\"], \"ans\": 2, \"why\": \"\\\\(\\\\frac{R}{H} = \\\\frac{4}{\\\\tan\\\\alpha}\\\\) ⇒ \\\\(\\\\tan\\\\alpha = \\\\frac{4H}{R}\\\\); \\\\(\\\\alpha = 60^{\\\\circ}\\\\) হলে \\\\(\\\\frac{R}{H} = \\\\frac{4}{\\\\sqrt{3}}\\\\), অর্থাৎ \\\\(R : H = 4 : \\\\sqrt{3}\\\\)।\"}, {\"q\": \"আয়তাকার রুমের মাঝে 3 mole অক্সিজেন গ্যাস \\\\(27^{\\\\circ}\\\\mathrm{C}\\\\) তাপমাত্রায় অবস্থান করছে। রুমের মাত্রা \\\\(5 \\\\times 3 \\\\times 2\\\\) [m এককে]। আয়তাকার রুমটিতে অক্সিজেন গ্যাসের চাপ কত? [BUET Preli 22-23]\", \"opts\": [\"250 Pa\", \"250 Pa\", \"450 Pa\", \"150 Pa\"], \"ans\": 0, \"why\": \"\\\\(V = 5 \\\\times 3 \\\\times 2 = 30\\\\ \\\\mathrm{m^3}\\\\), \\\\(T = 300\\\\ \\\\mathrm{K}\\\\); \\\\(P = \\\\frac{nRT}{V} = \\\\frac{3 \\\\times 8.314 \\\\times 300}{30} = 249.42\\\\ \\\\mathrm{Pa} \\\\approx 250\\\\ \\\\mathrm{Pa}\\\\)।\"}, {\"q\": \"যেসব তরল কাঁচকে ভেজায় না তাদের স্পর্শ কোণ কত? [BUET Preli 22-23]\", \"opts\": [\"\\\\(90^{\\\\circ}\\\\) অপেক্ষা ছোট\", \"\\\\(90^{\\\\circ}\\\\)\", \"\\\\(90^{\\\\circ}\\\\) অপেক্ষা বড়\", \"b & c\"], \"ans\": 2, \"why\": \"কাঁচকে ভেজায় এমন তরলের স্পর্শ কোণ \\\\(0^{\\\\circ} < \\\\theta < 90^{\\\\circ}\\\\); ভেজায় না এমন তরলের (যেমন পারদ) ক্ষেত্রে \\\\(90^{\\\\circ} < \\\\theta < 180^{\\\\circ}\\\\)।\"}, {\"q\": \"\\\\(5\\\\ \\\\mathrm{ms^{-1}}\\\\) বেগে প্রবাহমান স্রোত বিশিষ্ট একটি নদীতে \\\\(10\\\\ \\\\mathrm{ms^{-1}}\\\\) বেগে চলমান নৌকা 1 hour যাত্রা করে সোজা অপর পাড়ে গিয়ে পৌঁছায়। তাহলে নদীর প্রস্থ কত হবে? [BUET Preli 22-23]\", \"opts\": [\"30 km\", \"31 km\", \"32 km\", \"29 km\"], \"ans\": 1, \"why\": \"সোজা পাড়ি দিতে নৌকার দিক স্রোতের সাপেক্ষে \\\\(\\\\alpha = \\\\cos^{-1}\\\\left(-\\\\frac{5}{10}\\\\right) = 120^{\\\\circ}\\\\); প্রস্থ \\\\(d = t \\\\cdot v\\\\sin120^{\\\\circ} = 3600 \\\\times 10 \\\\times \\\\sin 120^{\\\\circ} = 31.18\\\\ \\\\mathrm{km} \\\\approx 31\\\\ \\\\mathrm{km}\\\\)।\"}, {\"q\": \"স্ক্রু গজের পিচ \\\\(0.05\\\\ \\\\mathrm{cm}\\\\) এবং বৃত্তাকার স্কেলের ভাগসংখ্যা 50 হলে, লঘিষ্ঠ গণনের মান কত? [BUET Preli 22-23]\", \"opts\": [\"0.01 mm\", \"0.02 mm\", \"0.05 mm\", \"0.1 mm\"], \"ans\": 0, \"why\": \"লঘিষ্ঠ গণন \\\\(= \\\\frac{\\\\text{পিচ}}{\\\\text{বৃত্তাকার স্কেলের ভাগসংখ্যা}} = \\\\frac{0.05 \\\\times 10}{50} = 0.01\\\\ \\\\mathrm{mm}\\\\)।\"}, {\"q\": \"একটি বস্তু \\\\(60\\\\ \\\\mathrm{cms^{-1}}\\\\) বেগে গতিশীল অবস্থায় একটি স্থির বস্তুর সঙ্গে স্থিতিস্থাপক সংঘর্ষে লিপ্ত হলো। সংঘর্ষের পর প্রথম বস্তুর বেগ \\\\(40\\\\ \\\\mathrm{cms^{-1}}\\\\) হলে, ২য় বস্তুর বেগ কত? [ভর সমান] [BUET Preli 22-23]\", \"opts\": [\"\\\\(100\\\\ \\\\mathrm{cms^{-1}}\\\\)\", \"\\\\(20\\\\ \\\\mathrm{cms^{-1}}\\\\)\", \"\\\\(40\\\\ \\\\mathrm{cms^{-1}}\\\\)\", \"\\\\(45\\\\ \\\\mathrm{cms^{-1}}\\\\)\"], \"ans\": 1, \"why\": \"ভরবেগের সংরক্ষণ থেকে: \\\\(m \\\\times 60 + 0 = m \\\\times 40 + m v_2\\\\) ⇒ \\\\(v_2 = 60 - 40 = 20\\\\ \\\\mathrm{cms^{-1}}\\\\)। (লক্ষ্য করো: এই তথ্যে শক্তি সংরক্ষিত থাকে না, অর্থাৎ সংঘর্ষটি প্রকৃতপক্ষে পূর্ণ স্থিতিস্থাপক নয় — বইয়ের ছাপানো উত্তরও ভরবেগ-সংরক্ষণ অনুযায়ী \\\\(20\\\\ \\\\mathrm{cms^{-1}}\\\\))।\"}, {\"q\": \"\\\\(300\\\\ \\\\mathrm{kg}\\\\) ভরের একটি নৌকা থেকে \\\\(80\\\\ \\\\mathrm{kg}\\\\) ও \\\\(60\\\\ \\\\mathrm{kg}\\\\) ভরের দুইজন ব্যক্তি দুইদিকে \\\\(2\\\\ \\\\mathrm{ms^{-1}}\\\\) বেগে লাফ দিল। নৌকার বর্তমান বেগের মান কত হবে? [BUET Preli 22-23]\", \"opts\": [\"\\\\(0.1\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(0.909\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(0.98\\\\ \\\\mathrm{ms^{-1}}\\\\)\", \"\\\\(0.99\\\\ \\\\mathrm{ms^{-1}}\\\\)\"], \"ans\": 0, \"why\": \"ভরবেগ সংরক্ষণে \\\\(300 v = -(80 \\\\times 2 - 60 \\\\times 2) = -40\\\\) ⇒ \\\\(|v| = 0.133 \\\\approx 0.1\\\\ \\\\mathrm{ms^{-1}}\\\\) (60 kg ভরের ব্যক্তি যেদিকে লাফ দিয়েছে, নৌকা সেদিকে যাবে)।\"}]"}, "adm-buet-2013-14": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট ২০১৩-১৪", "chapter": "Admission", "level": "বুয়েট", "minutes": 14, "qjson": "[{\"q\": \"\\\\(4.0 \\\\times 10^{-8}\\\\) C মানের সমান ও বিপরীত জাতীয় দুটি আধান 6.0 cm ব্যবধানে A ও B বিন্দুতে অবস্থিত। আধানদ্বয়ের সংযোগ সরলরেখা AB এর লম্ব সমদ্বিখণ্ডকের উপর 4.0 cm দূরে P বিন্দুতে স্থাপিত \\\\(1.0 \\\\times 10^{-8}\\\\) C আধানের উপর ক্রিয়াশীল লব্ধি বলের মান কত? \\\\(\\\\left(\\\\frac{1}{4\\\\pi\\\\varepsilon_0} = 9 \\\\times 10^{9}\\\\ \\\\text{Nm}^2\\\\text{C}^{-2}\\\\right)\\\\) [BUET 13-14]\", \"opts\": [\"\\\\(1.44 \\\\times 10^{-3}\\\\) N\", \"\\\\(1.728 \\\\times 10^{-3}\\\\) N\", \"\\\\(2.88 \\\\times 10^{-3}\\\\) N\", \"\\\\(2.304 \\\\times 10^{-3}\\\\) N\"], \"ans\": 1, \"why\": \"\\\\(PA = PB = \\\\sqrt{3^2 + 4^2} = 5\\\\) cm; প্রতিটি আধানের জন্য বল \\\\(F = 9 \\\\times 10^{9} \\\\times \\\\frac{(10 \\\\times 40) \\\\times 10^{-18}}{0.05^2} = 1.44 \\\\times 10^{-3}\\\\) N; লব্ধি \\\\(= 2F\\\\cos 53.13° = 1.728 \\\\times 10^{-3}\\\\) N।\"}, {\"q\": \"A ও B বিন্দুতে যথাক্রমে \\\\(+4.0 \\\\times 10^{-8}\\\\) C ও \\\\(-4.0 \\\\times 10^{-8}\\\\) C আধান 6.0 cm ব্যবধানে অবস্থিত। AB এর লম্ব সমদ্বিখণ্ডকের উপর 4.0 cm দূরে P বিন্দুতে রাখা \\\\(1.0 \\\\times 10^{-8}\\\\) C আধানের উপর লব্ধি বল PB রেখার সাথে কত কোণ উৎপন্ন করে? [BUET 13-14]\", \"opts\": [\"\\\\(36.87°\\\\)\", \"\\\\(106.26°\\\\)\", \"\\\\(53.13°\\\\)\", \"\\\\(90°\\\\)\"], \"ans\": 2, \"why\": \"লব্ধি বল AB-এর সমান্তরাল দিকে ক্রিয়া করে; উপাংশ বিশ্লেষণে দিক \\\\(= \\\\tan^{-1}\\\\left(\\\\frac{F\\\\sin\\\\alpha}{F + F\\\\cos\\\\alpha}\\\\right) = 53.13°\\\\), যেখানে বলদ্বয়ের অন্তর্গত কোণ \\\\(\\\\alpha = 106.26°\\\\)।\"}, {\"q\": \"\\\\(2\\\\ \\\\mu\\\\text{F}\\\\) ধারকত্ববিশিষ্ট একটি ধারককে চার্জিত করার পর একটি পরিবাহী তার দ্বারা এটিকে চার্জমুক্ত করা হলো। ধারকে সঞ্চিত সমস্ত শক্তিই তারটিকে উত্তপ্ত করতে খরচ হলো। এই শক্তির পরিমাণ 214.3 ক্যালরি হলে, কত ভোল্টে ধারকটিকে চার্জিত করা হয়েছিল? [BUET 13-14]\", \"opts\": [\"\\\\(2.12 \\\\times 10^{4}\\\\) V\", \"\\\\(4.24 \\\\times 10^{4}\\\\) V\", \"\\\\(3 \\\\times 10^{3}\\\\) V\", \"\\\\(3 \\\\times 10^{4}\\\\) V\"], \"ans\": 3, \"why\": \"সঞ্চিত শক্তি \\\\(\\\\frac{1}{2}CV^2 = 214.3 \\\\times 4.2 = 900.06\\\\) J \\\\(\\\\Rightarrow V = \\\\sqrt{\\\\frac{2 \\\\times 900.06}{2 \\\\times 10^{-6}}} \\\\approx 3 \\\\times 10^{4}\\\\) V।\"}, {\"q\": \"একটি পারমাণবিক বোমা বিস্ফোরিত হলে সৃষ্ট আগুনের গোলকের ব্যাসার্ধ হয় 100 m এবং এর তাপমাত্রা \\\\(10^{5}\\\\) K। যদি গোলকটি রুদ্ধতাপ পদ্ধতিতে 1000 m ব্যাসার্ধে বর্ধিত হয় তবে এর সম্ভাব্য তাপমাত্রা কত হবে? (আপেক্ষিক তাপদ্বয়ের অনুপাত, \\\\(\\\\frac{C_p}{C_v} = 1.66\\\\)) [BUET 13-14]\", \"opts\": [\"\\\\(1047.13\\\\) K\", \"\\\\(10471.3\\\\) K\", \"\\\\(21880\\\\) K\", \"\\\\(104.71\\\\) K\"], \"ans\": 0, \"why\": \"রুদ্ধতাপ প্রসারণে \\\\(TV^{\\\\gamma-1}\\\\) ধ্রুবক এবং \\\\(V \\\\propto r^3\\\\); \\\\(T_2 = 10^{5} \\\\times \\\\left(\\\\frac{100}{1000}\\\\right)^{3\\\\gamma - 3} = 10^{5} \\\\times (0.1)^{1.98} = 1047.13\\\\) K।\"}, {\"q\": \"0°C তাপমাত্রায় 1 kg বরফকে 100°C তাপমাত্রার পানিতে পরিণত করতে এনট্রপির বৃদ্ধি কত হবে? (বরফ গলনের লীনতাপ \\\\(3.36 \\\\times 10^{5}\\\\ \\\\text{J kg}^{-1}\\\\), পানির আপেক্ষিক তাপ \\\\(4200\\\\ \\\\text{J kg}^{-1}\\\\text{K}^{-1}\\\\)) [BUET 13-14]\", \"opts\": [\"\\\\(1230.77\\\\ \\\\text{J K}^{-1}\\\\)\", \"\\\\(2541.62\\\\ \\\\text{J K}^{-1}\\\\)\", \"\\\\(1310.85\\\\ \\\\text{J K}^{-1}\\\\)\", \"\\\\(5083.23\\\\ \\\\text{J K}^{-1}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(\\\\Delta S = \\\\frac{mL_f}{273} + mS\\\\ln\\\\frac{373}{273} = \\\\frac{3.36 \\\\times 10^{5}}{273} + 4200 \\\\times \\\\ln(1.366) = 1230.77 + 1310.85 = 2541.62\\\\ \\\\text{J K}^{-1}\\\\)।\"}, {\"q\": \"বায়ুতে ইয়ং-এর দ্বি-চিড় পরীক্ষায় 6000 Å তরঙ্গদৈর্ঘ্যের আলো ব্যবহার করলে ডোরার ব্যবধান হয় 2.0 mm। যদি সমস্ত পরীক্ষাযন্ত্রটিকে 1.33 প্রতিসরাঙ্কের একটি তরলে ডুবানো হয় তাহলে ডোরার ব্যবধান কত হবে? [BUET 13-14]\", \"opts\": [\"\\\\(2.66\\\\) mm\", \"\\\\(2.0\\\\) mm\", \"\\\\(1.50\\\\) mm\", \"\\\\(1.33\\\\) mm\"], \"ans\": 2, \"why\": \"তরলে তরঙ্গদৈর্ঘ্য \\\\(\\\\mu\\\\) গুণ হ্রাস পায় এবং \\\\(\\\\beta = \\\\frac{\\\\lambda D}{a} \\\\propto \\\\frac{1}{\\\\mu}\\\\); সুতরাং \\\\(\\\\beta_2 = \\\\frac{2.0}{1.33} = 1.50\\\\) mm।\"}, {\"q\": \"কোনো ধাতুর কার্য অপেক্ষক 4 eV। ঐ ধাতুতে \\\\(10^{15}\\\\) Hz কম্পাঙ্কের আলোক রশ্মি আপতিত হলে সর্বোচ্চ কত গতিশক্তি নিয়ে ইলেকট্রন নিঃসৃত হতে পারবে? [BUET 13-14]\", \"opts\": [\"\\\\(2.26 \\\\times 10^{-19}\\\\) J\", \"\\\\(6.63 \\\\times 10^{-19}\\\\) J\", \"\\\\(6.40 \\\\times 10^{-19}\\\\) J\", \"\\\\(2.26 \\\\times 10^{-20}\\\\) J\"], \"ans\": 3, \"why\": \"\\\\(E_k = hf - \\\\phi = 6.626 \\\\times 10^{-34} \\\\times 10^{15} - 4 \\\\times 1.6 \\\\times 10^{-19} = 6.63 \\\\times 10^{-19} - 6.40 \\\\times 10^{-19} = 2.26 \\\\times 10^{-20}\\\\) J।\"}, {\"q\": \"2 mm ব্যাসের একটি ইস্পাতের তার \\\\(20^\\\\circ\\\\text{C}\\\\) তাপমাত্রায় দুইটি বিন্দুর মধ্যে টানটান অবস্থায় রাখা আছে। তাপমাত্রা \\\\(10^\\\\circ\\\\text{C}\\\\)-এ নেমে আসলে তারটির মধ্যে কত টান বল তৈরি হবে? (ইস্পাতের তাপীয় দৈর্ঘ্য-বৃদ্ধি গুণাঙ্ক \\\\(1.1\\\\times10^{-5}{}^{\\\\circ}\\\\text{C}^{-1}\\\\) এবং ইয়ং-এর গুণাঙ্ক \\\\(2.1\\\\times10^{11}\\\\,\\\\text{N/m}^2\\\\)) [BUET 13-14]\", \"opts\": [\"\\\\(36.29\\\\ \\\\text{N}\\\\)\", \"\\\\(72.57\\\\ \\\\text{N}\\\\)\", \"\\\\(145.14\\\\ \\\\text{N}\\\\)\", \"\\\\(7.26\\\\ \\\\text{N}\\\\)\"], \"ans\": 1, \"why\": \"তাপমাত্রা কমলে তার সংকুচিত হতে চায়, কিন্তু প্রান্ত আটকানো থাকায় টান তৈরি হয়: \\\\(F = YA\\\\alpha\\\\Delta\\\\theta = 2.1\\\\times10^{11}\\\\times\\\\pi(10^{-3})^2\\\\times1.1\\\\times10^{-5}\\\\times10 = 72.57\\\\ \\\\text{N}\\\\)।\"}, {\"q\": \"কোনো তেজস্ক্রিয় পদার্থের অর্ধায়ু 30 দিন। এর ক্ষয় ধ্রুবক \\\\(\\\\lambda\\\\) নির্ণয় কর। [BUET 13-14]\", \"opts\": [\"\\\\(0.0116\\\\ \\\\text{day}^{-1}\\\\)\", \"\\\\(0.0462\\\\ \\\\text{day}^{-1}\\\\)\", \"\\\\(0.0231\\\\ \\\\text{day}^{-1}\\\\)\", \"\\\\(0.0333\\\\ \\\\text{day}^{-1}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(\\\\lambda = \\\\frac{\\\\ln 2}{T_{1/2}} = \\\\frac{0.693}{30} = 0.0231\\\\ \\\\text{day}^{-1}\\\\)।\"}, {\"q\": \"কোনো তেজস্ক্রিয় পদার্থের অর্ধায়ু 30 দিন। কত সময় পর এর প্রারম্ভিক পরমাণু সংখ্যার এক অষ্টমাংশ অক্ষত থাকবে? [BUET 13-14]\", \"opts\": [\"60 দিন\", \"120 দিন\", \"240 দিন\", \"90 দিন\"], \"ans\": 3, \"why\": \"\\\\(\\\\frac{1}{8} = \\\\left(\\\\frac12\\\\right)^3\\\\), অর্থাৎ 3টি অর্ধায়ু অতিক্রান্ত হতে হবে: \\\\(t = 3\\\\times30 = 90\\\\) দিন।\"}, {\"q\": \"একটি বিমানবন্দরের রানওয়ের দৈর্ঘ্য 100 m। একটি উড়োজাহাজকে উড়ার পূর্ব মুহূর্তে \\\\(216\\\\ \\\\text{km/hr}\\\\) গতি সম্পন্ন হতে হয়। উড়োজাহাজটি \\\\(15\\\\ \\\\text{m/s}^2\\\\) ত্বরণে ত্বরান্বিত হলে রানওয়ে থেকে উড়তে সক্ষম হবে কি? [BUET 13-14]\", \"opts\": [\"হ্যাঁ, সক্ষম হবে\", \"না, আরও প্রায় 50 m দৈর্ঘ্য দরকার\", \"না, আরও প্রায় 20 m দৈর্ঘ্য দরকার\", \"হ্যাঁ, ঠিক 100 m-ই যথেষ্ট\"], \"ans\": 2, \"why\": \"প্রয়োজনীয় বেগ \\\\(v = 216/3.6 = 60\\\\ \\\\text{m/s}\\\\)। \\\\(s = \\\\frac{v^2}{2a} = \\\\frac{60^2}{2\\\\times15} = 120\\\\ \\\\text{m} > 100\\\\ \\\\text{m}\\\\), তাই সক্ষম হবে না; আরও \\\\(120-100 = 20\\\\) m দরকার।\"}, {\"q\": \"একটি উড়োজাহাজকে উড়ার পূর্ব মুহূর্তে \\\\(216\\\\ \\\\text{km/hr}\\\\) গতি সম্পন্ন হতে হয়। উড়োজাহাজটি \\\\(15\\\\ \\\\text{m/s}^2\\\\) সুষম ত্বরণে ত্বরান্বিত হলে রানওয়ের দৈর্ঘ্য সর্বনিম্ন কত হলে উড়োজাহাজটি উড়তে পারবে? [BUET 13-14]\", \"opts\": [\"\\\\(120\\\\ \\\\text{m}\\\\)\", \"\\\\(100\\\\ \\\\text{m}\\\\)\", \"\\\\(180\\\\ \\\\text{m}\\\\)\", \"\\\\(240\\\\ \\\\text{m}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(v = 60\\\\ \\\\text{m/s}\\\\), স্থিরাবস্থা থেকে \\\\(v^2 = 2as\\\\) ধরে \\\\(s = \\\\frac{60^2}{2\\\\times15} = 120\\\\ \\\\text{m}\\\\)।\"}, {\"q\": \"একটি সুতায় \\\\(y = 5\\\\cos\\\\frac{\\\\pi}{3}x\\\\,\\\\sin 40\\\\pi t\\\\) সমীকরণ অনুযায়ী স্থির তরঙ্গ স্পন্দিত হচ্ছে (x ও y-এর একক cm, t-এর একক sec)। যে তরঙ্গ দুইটির উপরিপাতনের ফলে এই স্পন্দনের সৃষ্টি হয়, তাদের প্রতিটির বিস্তার কত? [BUET 13-14]\", \"opts\": [\"\\\\(5\\\\ \\\\text{cm}\\\\)\", \"\\\\(2.5\\\\ \\\\text{cm}\\\\)\", \"\\\\(10\\\\ \\\\text{cm}\\\\)\", \"\\\\(1.25\\\\ \\\\text{cm}\\\\)\"], \"ans\": 1, \"why\": \"দুইটি সমান বিস্তারের \\\\(A\\\\) তরঙ্গের উপরিপাতনে স্থির তরঙ্গের বিস্তার হয় \\\\(2A\\\\)। এখানে \\\\(2A = 5\\\\ \\\\text{cm}\\\\), সুতরাং প্রতিটি তরঙ্গের বিস্তার \\\\(A = 2.5\\\\ \\\\text{cm}\\\\)।\"}, {\"q\": \"একটি সুতায় \\\\(y = 5\\\\cos\\\\frac{\\\\pi}{3}x\\\\,\\\\sin 40\\\\pi t\\\\) সমীকরণ অনুযায়ী স্থির তরঙ্গ স্পন্দিত হচ্ছে (x ও y-এর একক cm, t-এর একক sec)। উপাদান তরঙ্গ দুইটির বেগ নির্ণয় কর। [BUET 13-14]\", \"opts\": [\"\\\\(60\\\\ \\\\text{cm/s}\\\\)\", \"\\\\(240\\\\ \\\\text{cm/s}\\\\)\", \"\\\\(40\\\\pi\\\\ \\\\text{cm/s}\\\\)\", \"\\\\(120\\\\ \\\\text{cm/s}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(\\\\omega = 40\\\\pi\\\\), \\\\(k = \\\\pi/3\\\\) rad/cm। তরঙ্গ বেগ \\\\(v = \\\\frac{\\\\omega}{k} = \\\\frac{40\\\\pi}{\\\\pi/3} = 120\\\\ \\\\text{cm/s}\\\\)।\"}]"}, "adm-buet-2010-11": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট ২০১০-১১", "chapter": "Admission", "level": "বুয়েট", "minutes": 10, "qjson": "[{\"q\": \"1200 kg ভরের একটি গাড়ীর ইঞ্জিনের ক্ষমতা 134.05 HP ও কর্মদক্ষতা 90%। গাড়িটিকে স্থিরাবস্থা থেকে \\\\(30\\\\ \\\\text{m/s}\\\\) বেগে আনতে ন্যূনতম কত সময় লাগবে? (1 HP \\\\(= 0.746\\\\ \\\\text{kW}\\\\)) [BUET 10-11]\", \"opts\": [\"প্রায় 6 s\", \"প্রায় 3 s\", \"প্রায় 12 s\", \"প্রায় 9 s\"], \"ans\": 0, \"why\": \"প্রাপ্ত ক্ষমতা \\\\(P = 134.05\\\\times746\\\\times0.90 = 90001\\\\ \\\\text{W}\\\\)। কাজ-শক্তি উপপাদ্যে \\\\(Pt = \\\\frac12mv^2 = \\\\frac12\\\\times1200\\\\times30^2 = 540000\\\\ \\\\text{J}\\\\), সুতরাং \\\\(t = \\\\frac{540000}{90001} \\\\approx 6\\\\ \\\\text{s}\\\\)।\"}, {\"q\": \"একটি রিমোট সেন্সিং স্যাটেলাইট পৃথিবীর চারদিকে ভূ-পৃষ্ঠ হতে 250 km উপরে বৃত্তাকার পথে ঘুরছে। এই পথে স্যাটেলাইটটির গতিবেগ নির্ণয় কর। (\\\\(R_e = 6400\\\\ \\\\text{km}\\\\), \\\\(g = 9.8\\\\ \\\\text{m/s}^2\\\\)) [BUET 10-11]\", \"opts\": [\"\\\\(7919\\\\ \\\\text{m/s}\\\\)\", \"\\\\(7769.3\\\\ \\\\text{m/s}\\\\)\", \"\\\\(7530\\\\ \\\\text{m/s}\\\\)\", \"\\\\(11000\\\\ \\\\text{m/s}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(v = \\\\sqrt{\\\\frac{GM}{R_e+h}} = R_e\\\\sqrt{\\\\frac{g}{R_e+h}} = 6.4\\\\times10^6\\\\sqrt{\\\\frac{9.8}{6.65\\\\times10^6}} = 7769.3\\\\ \\\\text{m/s}\\\\)।\"}, {\"q\": \"একটি রিমোট সেন্সিং স্যাটেলাইট পৃথিবীর চারদিকে ভূ-পৃষ্ঠ হতে 250 km উপরে বৃত্তাকার পথে ঘুরছে। স্যাটেলাইটটির ঘূর্ণনকাল (পর্যায়কাল) নির্ণয় কর। (\\\\(R_e = 6400\\\\ \\\\text{km}\\\\), \\\\(g = 9.8\\\\ \\\\text{m/s}^2\\\\), কক্ষীয় বেগ \\\\(7769.3\\\\ \\\\text{m/s}\\\\)) [BUET 10-11]\", \"opts\": [\"\\\\(5170\\\\ \\\\text{s}\\\\)\", \"\\\\(86400\\\\ \\\\text{s}\\\\)\", \"\\\\(5377.98\\\\ \\\\text{s}\\\\)\", \"\\\\(6075\\\\ \\\\text{s}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(T = \\\\frac{2\\\\pi(R_e+h)}{v} = \\\\frac{2\\\\pi\\\\times6.65\\\\times10^6}{7769.3} = 5377.98\\\\ \\\\text{s}\\\\)।\"}, {\"q\": \"যখন 1 kg আদর্শ ভর একটি চলমান প্লাটফর্মের উপর রাখা হয় তখন তার স্পন্দনের হার \\\\(125\\\\ \\\\text{vib min}^{-1}\\\\)। অজানা কত ভরের জন্য স্পন্দনের হার \\\\(243\\\\ \\\\text{vib min}^{-1}\\\\) হবে? (চলমান প্লাটফর্মের ভর অগ্রাহ্য কর।) [BUET 10-11]\", \"opts\": [\"\\\\(1.94\\\\ \\\\text{kg}\\\\)\", \"\\\\(0.514\\\\ \\\\text{kg}\\\\)\", \"\\\\(0.2646\\\\ \\\\text{kg}\\\\)\", \"\\\\(0.0685\\\\ \\\\text{kg}\\\\)\"], \"ans\": 2, \"why\": \"স্প্রিং-ভর ব্যবস্থায় \\\\(f \\\\propto \\\\frac{1}{\\\\sqrt{m}}\\\\)। তাই \\\\(\\\\frac{125}{243} = \\\\sqrt{\\\\frac{m_2}{1}}\\\\), অর্থাৎ \\\\(m_2 = \\\\left(\\\\frac{125}{243}\\\\right)^2 = 0.2646\\\\ \\\\text{kg}\\\\)।\"}, {\"q\": \"বায়ু মাধ্যমে \\\\(50000\\\\ \\\\text{V/m}\\\\) সুষম বৈদ্যুতিক ক্ষেত্রে দুটি বৃত্তাকার পাত \\\\(0.002\\\\ \\\\text{m}\\\\) দূরত্বে সমান্তরাল অবস্থায় আছে। প্রতিটি পাতের ব্যাসার্ধ \\\\(0.08\\\\ \\\\text{m}\\\\)। গঠিত ধারকটিতে মোট সঞ্চিত শক্তি নির্ণয় কর। [BUET 10-11]\", \"opts\": [\"\\\\(4.45\\\\times10^{-7}\\\\ \\\\text{J}\\\\)\", \"\\\\(8.90\\\\times10^{-7}\\\\ \\\\text{J}\\\\)\", \"\\\\(2.23\\\\times10^{-7}\\\\ \\\\text{J}\\\\)\", \"\\\\(4.45\\\\times10^{-5}\\\\ \\\\text{J}\\\\)\"], \"ans\": 0, \"why\": \"পাতদ্বয়ের বিভব পার্থক্য \\\\(V = Ed = 100\\\\ \\\\text{V}\\\\), ধারকত্ব \\\\(C = \\\\frac{\\\\varepsilon_0 A}{d} = \\\\frac{8.854\\\\times10^{-12}\\\\times\\\\pi(0.08)^2}{0.002}\\\\)। সঞ্চিত শক্তি \\\\(U = \\\\frac12CV^2 = 4.45\\\\times10^{-7}\\\\ \\\\text{J}\\\\)।\"}, {\"q\": \"একটি জলবিদ্যুৎ কেন্দ্রে বাঁধের উচ্চতা 10 m। 1 MW বিদ্যুৎ উৎপাদনের জন্য প্রতি সেকেন্ডে টারবাইনটির ব্লেডগুলোর উপর কত কিলোগ্রাম পানি পড়তে হবে? [BUET 10-11]\", \"opts\": [\"\\\\(1020.4\\\\ \\\\text{kg}\\\\)\", \"\\\\(10204.08\\\\ \\\\text{kg}\\\\)\", \"\\\\(100000\\\\ \\\\text{kg}\\\\)\", \"\\\\(9800\\\\ \\\\text{kg}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(P = \\\\frac{mgh}{t}\\\\) থেকে প্রতি সেকেন্ডে পতিত পানির ভর \\\\(\\\\frac{m}{t} = \\\\frac{P}{gh} = \\\\frac{10^6}{9.8\\\\times10} = 10204.08\\\\ \\\\text{kg}\\\\)।\"}, {\"q\": \"একটি 40 W-এর বাতি থেকে সবুজ আলো (\\\\(\\\\lambda = 555\\\\ \\\\text{nm}\\\\)) বিকিরিত হচ্ছে। বাতিটির তড়িৎ শক্তির 3% যদি আলোক শক্তিতে রূপান্তরিত হয়, তবে প্রতি সেকেন্ডে বাতি হতে কত সংখ্যক ফোটন নির্গত হয়? [BUET 10-11]\", \"opts\": [\"\\\\(3.35\\\\times10^{18}\\\\)\", \"\\\\(1.12\\\\times10^{20}\\\\)\", \"\\\\(3.35\\\\times10^{16}\\\\)\", \"\\\\(1.01\\\\times10^{18}\\\\)\"], \"ans\": 0, \"why\": \"আলোকে রূপান্তরিত ক্ষমতা \\\\(40\\\\times3\\\\% = 1.2\\\\ \\\\text{W}\\\\)। একটি ফোটনের শক্তি \\\\(\\\\frac{hc}{\\\\lambda} = \\\\frac{6.626\\\\times10^{-34}\\\\times3\\\\times10^8}{555\\\\times10^{-9}} = 3.58\\\\times10^{-19}\\\\ \\\\text{J}\\\\)। ফোটন সংখ্যা \\\\(n = \\\\frac{1.2}{3.58\\\\times10^{-19}} = 3.35\\\\times10^{18}\\\\)।\"}, {\"q\": \"একটি কাঠের চাকার পরিধি বরাবর একটি লোহার চুড়ি পরানোর জন্য মনস্থ করা হল। চাকার ব্যাস 1.10 m এবং লোহার চুড়ির ভেতরের ব্যাস 1.098 m। লোহার চুড়িটির আদি তাপমাত্রা \\\\(20^\\\\circ\\\\text{C}\\\\) হলে একে কত তাপমাত্রায় উত্তপ্ত করতে হবে যাতে এটি ঠিক কাঠের চাকার উপর বসে পড়ে? (লোহার \\\\(\\\\alpha = 1.2\\\\times10^{-5}{}^{\\\\circ}\\\\text{C}^{-1}\\\\)) [BUET 10-11]\", \"opts\": [\"\\\\(151.8^\\\\circ\\\\text{C}\\\\)\", \"\\\\(91.7^\\\\circ\\\\text{C}\\\\)\", \"\\\\(183.3^\\\\circ\\\\text{C}\\\\)\", \"প্রায় \\\\(171.8^\\\\circ\\\\text{C}\\\\)\"], \"ans\": 3, \"why\": \"ব্যাসের আপেক্ষিক বৃদ্ধি দরকার \\\\(\\\\frac{1.10-1.098}{1.098} = 1.82\\\\times10^{-3}\\\\)। \\\\(\\\\Delta\\\\theta = \\\\frac{1.82\\\\times10^{-3}}{1.2\\\\times10^{-5}} = 151.8^\\\\circ\\\\text{C}\\\\), সুতরাং চূড়ান্ত তাপমাত্রা \\\\(20 + 151.8 = 171.8^\\\\circ\\\\text{C}\\\\)।\"}, {\"q\": \"একটি স্লাইড প্রোজেক্টর দিয়ে \\\\(35\\\\ \\\\text{mm} \\\\times 23\\\\ \\\\text{mm}\\\\) আকারের একটি স্লাইডকে \\\\(2\\\\ \\\\text{m} \\\\times 2\\\\ \\\\text{m}\\\\) আকারের একটি পর্দায় প্রক্ষেপণ করা হবে। পর্দাটি লেন্স হতে 10 m দূরে থাকলে লেন্সের ফোকাস দূরত্ব নির্ণয় কর। [BUET 10-11]\", \"opts\": [\"প্রায় \\\\(17.2\\\\ \\\\text{cm}\\\\)\", \"\\\\(10\\\\ \\\\text{cm}\\\\)\", \"\\\\(57.1\\\\ \\\\text{cm}\\\\)\", \"\\\\(175\\\\ \\\\text{cm}\\\\)\"], \"ans\": 0, \"why\": \"বিবর্ধন \\\\(m = \\\\frac{2000}{35} = 57.1\\\\); প্রতিবিম্ব দূরত্ব \\\\(v = 10\\\\ \\\\text{m}\\\\) হলে বস্তু দূরত্ব \\\\(u = \\\\frac{v}{m} = 0.175\\\\ \\\\text{m}\\\\)। লেন্সের সূত্রে \\\\(\\\\frac{1}{f} = \\\\frac{1}{10} + \\\\frac{1}{0.175}\\\\) থেকে \\\\(f = 0.172\\\\ \\\\text{m} \\\\approx 17.2\\\\ \\\\text{cm}\\\\)।\"}, {\"q\": \"250 পাক সংখ্যা বিশিষ্ট বৃত্তাকার কয়েলের ব্যাসার্ধ 5 cm। কয়েলটিতে বিদ্যুৎ প্রবাহের পরিমাণ 20 A হলে কয়েলের কেন্দ্রে চৌম্বকক্ষেত্রের মান কত? (\\\\(\\\\mu_0 = 4\\\\pi\\\\times10^{-7}\\\\,\\\\text{TmA}^{-1}\\\\)) [BUET 10-11]\", \"opts\": [\"\\\\(6.28\\\\times10^{-3}\\\\ \\\\text{T}\\\\)\", \"\\\\(6.28\\\\times10^{-2}\\\\ \\\\text{T}\\\\)\", \"\\\\(3.14\\\\times10^{-2}\\\\ \\\\text{T}\\\\)\", \"\\\\(1.26\\\\times10^{-2}\\\\ \\\\text{T}\\\\)\"], \"ans\": 1, \"why\": \"কয়েলের কেন্দ্রে \\\\(B = \\\\frac{\\\\mu_0 N I}{2r} = \\\\frac{4\\\\pi\\\\times10^{-7}\\\\times250\\\\times20}{2\\\\times0.05} = 6.28\\\\times10^{-2}\\\\ \\\\text{T}\\\\)।\"}]"}, "adm-buet-2005-06": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট ২০০৫-০৬", "chapter": "Admission", "level": "বুয়েট", "minutes": 15, "qjson": "[{\"q\": \"\\\\(8\\\\,\\\\mathrm{kg}\\\\) ভরের একটি বস্তু \\\\(10\\\\,\\\\mathrm{m}\\\\) উপর হতে পড়ে বালিতে \\\\(50\\\\,\\\\mathrm{cm}\\\\) প্রবেশ করে থেমে গেল। বস্তুটির উপর বালির গড় বাধা নির্ণয় কর। [BUET 05-06]\", \"opts\": [\"\\\\(1568\\\\,\\\\mathrm{N}\\\\)\", \"\\\\(1646.4\\\\,\\\\mathrm{N}\\\\)\", \"\\\\(823.2\\\\,\\\\mathrm{N}\\\\)\", \"\\\\(16464\\\\,\\\\mathrm{N}\\\\)\"], \"ans\": 1, \"why\": \"কাজ-শক্তি উপপাদ্যে মোট পতন দূরত্ব \\\\((h+x)\\\\) ধরে \\\\(mg(h+x)=Fx\\\\) ⇒ \\\\(F=\\\\frac{8\\\\times9.8\\\\times(10+0.5)}{0.5}=1646.4\\\\,\\\\mathrm{N}\\\\)।\"}, {\"q\": \"ভূ-পৃষ্ঠ হতে খাড়া উপরের দিকে একটি রকেটকে \\\\(5\\\\,\\\\mathrm{kms^{-1}}\\\\) দ্রুতিতে উৎক্ষেপণ করা হলো। রকেটটি ঠিক ফিরে আসার মুহূর্তে (সর্বোচ্চ বিন্দুতে) ভূ-পৃষ্ঠ থেকে কত উচ্চতায় পৌঁছাবে তা বের কর। (পৃথিবীর ভর \\\\(=6.0\\\\times10^{24}\\\\,\\\\mathrm{kg}\\\\), পৃথিবীর ব্যাসার্ধ \\\\(=6.4\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\), \\\\(G=6.67\\\\times10^{-11}\\\\,\\\\mathrm{Nm^2kg^{-2}}\\\\)) [BUET 05-06]\", \"opts\": [\"\\\\(1.28\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(1.60\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(3.20\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(6.40\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\)\"], \"ans\": 1, \"why\": \"শক্তির সংরক্ষণ: \\\\(-\\\\frac{GMm}{R}+\\\\frac{1}{2}mv^2=-\\\\frac{GMm}{R+h}\\\\) ⇒ \\\\(R+h\\\\approx8.0\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\) ⇒ \\\\(h\\\\approx1.60\\\\times10^{6}\\\\,\\\\mathrm{m}\\\\)।\"}, {\"q\": \"সরল ছন্দিত স্পন্দনসম্পন্ন একটি বস্তুর বেগ \\\\(3\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(4\\\\,\\\\mathrm{m}\\\\) এবং বেগ \\\\(4\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(3\\\\,\\\\mathrm{m}\\\\)। দোলনের বিস্তার নির্ণয় কর। [BUET 05-06]\", \"opts\": [\"\\\\(7\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(6\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(5\\\\,\\\\mathrm{m}\\\\)\", \"\\\\(3.5\\\\,\\\\mathrm{m}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(v=\\\\omega\\\\sqrt{A^2-x^2}\\\\) থেকে \\\\(\\\\frac{3}{4}=\\\\frac{\\\\sqrt{A^2-16}}{\\\\sqrt{A^2-9}}\\\\) ⇒ বর্গ করে \\\\(A^2=25\\\\) ⇒ \\\\(A=5\\\\,\\\\mathrm{m}\\\\)।\"}, {\"q\": \"সরল ছন্দিত স্পন্দনসম্পন্ন একটি বস্তুর বেগ \\\\(3\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(4\\\\,\\\\mathrm{m}\\\\) এবং বেগ \\\\(4\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(3\\\\,\\\\mathrm{m}\\\\)। দোলনের পর্যায়কাল নির্ণয় কর। [BUET 05-06]\", \"opts\": [\"\\\\(\\\\pi\\\\,\\\\mathrm{s}\\\\)\", \"\\\\(2\\\\pi\\\\,\\\\mathrm{s}\\\\)\", \"\\\\(4\\\\pi\\\\,\\\\mathrm{s}\\\\)\", \"\\\\(1\\\\,\\\\mathrm{s}\\\\)\"], \"ans\": 1, \"why\": \"বিস্তার \\\\(A=5\\\\,\\\\mathrm{m}\\\\) হলে \\\\(3=\\\\omega\\\\sqrt{25-16}=3\\\\omega\\\\) ⇒ \\\\(\\\\omega=1\\\\,\\\\mathrm{rad/s}\\\\); \\\\(T=\\\\frac{2\\\\pi}{\\\\omega}=2\\\\pi\\\\,\\\\mathrm{s}\\\\)।\"}, {\"q\": \"সরল ছন্দিত স্পন্দনসম্পন্ন একটি বস্তুর বেগ \\\\(3\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(4\\\\,\\\\mathrm{m}\\\\) এবং বেগ \\\\(4\\\\,\\\\mathrm{ms^{-1}}\\\\) যখন সরণ \\\\(3\\\\,\\\\mathrm{m}\\\\)। বস্তুটির ভর \\\\(50\\\\,\\\\mathrm{kg}\\\\) হলে দোলনের মোট শক্তি নির্ণয় কর। [BUET 05-06]\", \"opts\": [\"\\\\(1250\\\\,\\\\mathrm{J}\\\\)\", \"\\\\(312.5\\\\,\\\\mathrm{J}\\\\)\", \"\\\\(2500\\\\,\\\\mathrm{J}\\\\)\", \"\\\\(625\\\\,\\\\mathrm{J}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(A=5\\\\,\\\\mathrm{m}\\\\), \\\\(\\\\omega=1\\\\,\\\\mathrm{rad/s}\\\\) পেয়ে, \\\\(E_{total}=\\\\frac{1}{2}m\\\\omega^2A^2=\\\\frac{1}{2}\\\\times50\\\\times1\\\\times25=625\\\\,\\\\mathrm{J}\\\\)।\"}, {\"q\": \"শ্রেণি সমবায়ে সজ্জিত দুটি পরিবাহীর রোধ \\\\(40\\\\,\\\\Omega\\\\), যা সমান্তরাল সমবায়ে \\\\(7.5\\\\,\\\\Omega\\\\) হয়। প্রতিটি পরিবাহীর রোধ বের কর। [BUET 05-06]\", \"opts\": [\"\\\\(20\\\\,\\\\Omega\\\\) ও \\\\(20\\\\,\\\\Omega\\\\)\", \"\\\\(30\\\\,\\\\Omega\\\\) ও \\\\(10\\\\,\\\\Omega\\\\)\", \"\\\\(25\\\\,\\\\Omega\\\\) ও \\\\(15\\\\,\\\\Omega\\\\)\", \"\\\\(35\\\\,\\\\Omega\\\\) ও \\\\(5\\\\,\\\\Omega\\\\)\"], \"ans\": 1, \"why\": \"\\\\(R_1+R_2=40\\\\) এবং \\\\(\\\\frac{R_1R_2}{R_1+R_2}=7.5\\\\) ⇒ \\\\(R_1R_2=300\\\\); দুটি সমীকরণ সমাধান করে \\\\(R_1=30\\\\,\\\\Omega\\\\), \\\\(R_2=10\\\\,\\\\Omega\\\\)।\"}, {\"q\": \"কোনো ব্যতিচার পরীক্ষায় দুটি সুসংগত আলোর উৎসের প্রাবল্যের অনুপাত \\\\(25:4\\\\)। ব্যতিচার সজ্জার চরম বিন্দু ও অবম বিন্দুর প্রাবল্যের অনুপাত নির্ণয় করো। [BUET 05-06]\", \"opts\": [\"\\\\(25:4\\\\)\", \"\\\\(7:3\\\\)\", \"\\\\(625:16\\\\)\", \"\\\\(49:9\\\\)\"], \"ans\": 3, \"why\": \"\\\\(I\\\\propto a^2\\\\) ⇒ বিস্তারের অনুপাত \\\\(a_1:a_2=5:2\\\\); \\\\(\\\\frac{I_{max}}{I_{min}}=\\\\frac{(a_1+a_2)^2}{(a_1-a_2)^2}=\\\\frac{(5+2)^2}{(5-2)^2}=\\\\frac{49}{9}\\\\), অর্থাৎ \\\\(49:9\\\\)।\"}, {\"q\": \"কোনো মুহূর্তে একটি তেজস্ক্রিয় বস্তুর কাউন্ট রেট \\\\(4750\\\\) প্রতি মিনিটে; \\\\(5\\\\) মিনিট পর পাঠ \\\\(2700\\\\) প্রতি মিনিটে হয়। বস্তুটির ক্ষয় ধ্রুবক \\\\(\\\\lambda\\\\) কত? [BUET 05-06]\", \"opts\": [\"\\\\(0.113\\\\ \\\\mathrm{min^{-1}}\\\\)\", \"\\\\(0.056\\\\ \\\\mathrm{min^{-1}}\\\\)\", \"\\\\(0.226\\\\ \\\\mathrm{min^{-1}}\\\\)\", \"\\\\(1.13\\\\ \\\\mathrm{min^{-1}}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(\\\\lambda=\\\\frac{1}{t}\\\\ln\\\\frac{R_0}{R}=\\\\frac{1}{5}\\\\ln\\\\frac{4750}{2700}=0.113\\\\ \\\\mathrm{min^{-1}}\\\\)।\"}, {\"q\": \"কোনো মুহূর্তে একটি তেজস্ক্রিয় বস্তুর কাউন্ট রেট \\\\(4750\\\\) প্রতি মিনিটে; \\\\(5\\\\) মিনিট পর পাঠ \\\\(2700\\\\) প্রতি মিনিটে হয়। বস্তুটির অর্ধায়ু কত? [BUET 05-06]\", \"opts\": [\"\\\\(3.07\\\\) মিনিট\", \"\\\\(6.14\\\\) মিনিট\", \"\\\\(12.27\\\\) মিনিট\", \"\\\\(8.85\\\\) মিনিট\"], \"ans\": 1, \"why\": \"আগে \\\\(\\\\lambda=\\\\frac{1}{5}\\\\ln\\\\frac{4750}{2700}=0.113\\\\ \\\\mathrm{min^{-1}}\\\\); তারপর \\\\(T_{1/2}=\\\\frac{\\\\ln 2}{\\\\lambda}=\\\\frac{0.693}{0.113}\\\\approx 6.14\\\\) মিনিট।\"}, {\"q\": \"\\\\(20\\\\ \\\\mathrm{cm}\\\\) দৈর্ঘ্য ও \\\\(1\\\\ \\\\mathrm{cm}\\\\) ব্যাসার্ধের একটি ধাতব দণ্ড অপরিবাহী পদার্থে সম্পূর্ণ মোড়ানো। এক প্রান্ত \\\\(100^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রায় ও অন্য প্রান্ত \\\\(0^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রার বরফে রাখায় প্রতি \\\\(5\\\\) মিনিটে \\\\(25\\\\ \\\\mathrm{g}\\\\) বরফ গলে। দণ্ডটির তাপ পরিবাহিতাঙ্ক কত? (বরফ গলনের সুপ্ততাপ \\\\(80\\\\ \\\\mathrm{cal\\\\,g^{-1}}\\\\)) [BUET 05-06]\", \"opts\": [\"\\\\(0.21\\\\ \\\\mathrm{cal\\\\,cm^{-1}\\\\,s^{-1}{}^{\\\\circ} C^{-1}}\\\\)\", \"\\\\(0.85\\\\ \\\\mathrm{cal\\\\,cm^{-1}\\\\,s^{-1}{}^{\\\\circ} C^{-1}}\\\\)\", \"\\\\(0.42\\\\ \\\\mathrm{cal\\\\,cm^{-1}\\\\,s^{-1}{}^{\\\\circ} C^{-1}}\\\\)\", \"\\\\(1.27\\\\ \\\\mathrm{cal\\\\,cm^{-1}\\\\,s^{-1}{}^{\\\\circ} C^{-1}}\\\\)\"], \"ans\": 2, \"why\": \"প্রতি সেকেন্ডে পরিবাহিত তাপ \\\\(\\\\frac{25\\\\times 80}{300}=6.67\\\\ \\\\mathrm{cal/s}\\\\); \\\\(K=\\\\frac{(Q/t)\\\\,L}{A\\\\,\\\\Delta\\\\theta}=\\\\frac{6.67\\\\times 20}{\\\\pi (1)^2\\\\times 100}\\\\approx 0.42\\\\) (অর্থাৎ প্রায় \\\\(178\\\\ \\\\mathrm{W\\\\,m^{-1}K^{-1}}\\\\))।\"}, {\"q\": \"\\\\(3.0\\\\ \\\\mathrm{mm}\\\\) ও \\\\(6.0\\\\ \\\\mathrm{mm}\\\\) ব্যাসের দুটি কৈশিক নল একটি পানির পাত্রে খাড়াভাবে আংশিক ডুবিয়ে রাখা হলো। নল দুটিতে পানির অবতল তল দুটির মধ্যে উচ্চতার পার্থক্য কত? (পানির পৃষ্ঠটান \\\\(7.3\\\\times 10^{-2}\\\\ \\\\mathrm{N\\\\,m^{-1}}\\\\), স্পর্শ কোণ শূন্য, পানির ঘনত্ব \\\\(1.0\\\\times 10^{3}\\\\ \\\\mathrm{kg\\\\,m^{-3}}\\\\), \\\\(g=9.8\\\\ \\\\mathrm{m\\\\,s^{-2}}\\\\)) [BUET 05-06]\", \"opts\": [\"\\\\(9.93\\\\ \\\\mathrm{mm}\\\\)\", \"\\\\(4.97\\\\ \\\\mathrm{mm}\\\\)\", \"\\\\(2.48\\\\ \\\\mathrm{mm}\\\\)\", \"\\\\(14.9\\\\ \\\\mathrm{mm}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(h=\\\\frac{2T}{r\\\\rho g}\\\\): সরু নলে \\\\(h_1=9.93\\\\ \\\\mathrm{mm}\\\\), মোটা নলে \\\\(h_2=4.97\\\\ \\\\mathrm{mm}\\\\); পার্থক্য \\\\(h_1-h_2\\\\approx 4.97\\\\ \\\\mathrm{mm}\\\\)।\"}, {\"q\": \"একটি অগ্রগামী তরঙ্গের সমীকরণ \\\\(y=5\\\\sin(1508t-6.28x)\\\\); যেখানে \\\\(t\\\\)-এর একক সেকেন্ড এবং \\\\(x\\\\)-এর একক মিটার। তরঙ্গটির পর্যায়কাল কত? [BUET 05-06]\", \"opts\": [\"\\\\(4.17\\\\times 10^{-3}\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(6.63\\\\times 10^{-4}\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(0.24\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(1508\\\\ \\\\mathrm{s}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(\\\\omega=1508\\\\); \\\\(T=\\\\frac{2\\\\pi}{\\\\omega}=\\\\frac{2\\\\pi}{1508}\\\\approx 4.17\\\\times 10^{-3}\\\\ \\\\mathrm{s}\\\\)।\"}, {\"q\": \"একটি অগ্রগামী তরঙ্গের সমীকরণ \\\\(y=5\\\\sin(1508t-6.28x)\\\\); যেখানে \\\\(t\\\\)-এর একক সেকেন্ড এবং \\\\(x\\\\)-এর একক মিটার। তরঙ্গটির তরঙ্গদৈর্ঘ্য কত? [BUET 05-06]\", \"opts\": [\"\\\\(0.5\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(2\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(1\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(6.28\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(k=6.28\\\\); \\\\(\\\\lambda=\\\\frac{2\\\\pi}{k}=\\\\frac{2\\\\pi}{6.28}\\\\approx 1\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"একটি অগ্রগামী তরঙ্গের সমীকরণ \\\\(y=5\\\\sin(1508t-6.28x)\\\\); যেখানে \\\\(t\\\\)-এর একক সেকেন্ড এবং \\\\(x\\\\)-এর একক মিটার। তরঙ্গটির বেগ কত? [BUET 05-06]\", \"opts\": [\"\\\\(120\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)\", \"\\\\(240\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)\", \"\\\\(480\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)\", \"\\\\(9470\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(v=\\\\frac{\\\\omega}{k}=\\\\frac{1508}{6.28}\\\\approx 240\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)।\"}, {\"q\": \"দুটি মাধ্যমের বিভেদতলের এক পাশে \\\\(\\\\mu_a=1\\\\) ও অপর পাশে \\\\(\\\\mu_b=2\\\\)। \\\\(b\\\\) মাধ্যম থেকে একটি আলোকরশ্মি বিভেদতলের সাথে \\\\(75^\\\\circ\\\\) কোণ করে বিভেদতলের \\\\(O\\\\) বিন্দুতে আপতিত হলো। প্রতিসরিত রশ্মি অভিলম্বের সাথে কত কোণ উৎপন্ন করবে? [BUET 05-06]\", \"opts\": [\"পূর্ণ অভ্যন্তরীণ প্রতিফলন ঘটবে, প্রতিসরিত রশ্মি থাকবে না\", \"\\\\(15^\\\\circ\\\\)\", \"\\\\(31.2^\\\\circ\\\\)\", \"\\\\(48.6^\\\\circ\\\\)\"], \"ans\": 2, \"why\": \"আপতন কোণ (অভিলম্বের সাথে) \\\\(i=90^\\\\circ-75^\\\\circ=15^\\\\circ\\\\); স্নেলের সূত্রে \\\\(\\\\sin r=\\\\frac{\\\\mu_b}{\\\\mu_a}\\\\sin i=2\\\\sin 15^\\\\circ=0.518\\\\Rightarrow r\\\\approx 31.2^\\\\circ\\\\)।\"}]"}, "adm-buet-2002-03": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট ২০০২-০৩", "chapter": "Admission", "level": "বুয়েট", "minutes": 25, "qjson": "[{\"q\": \"একজন ব্যক্তি শ্বাস-প্রশ্বাসে \\\\(1.12\\\\ \\\\mathrm{litre}\\\\) বায়ু সেবন করলে সে মোট কতগুলো অণু সেবন করে? [সার্বজনীন গ্যাস ধ্রুবক \\\\(=8.314\\\\ \\\\mathrm{J\\\\,mol^{-1}K^{-1}}\\\\)] [BUET 02-03]\", \"opts\": [\"\\\\(3.01\\\\times10^{23}\\\\) টি\", \"\\\\(3.01\\\\times10^{22}\\\\) টি\", \"\\\\(6.02\\\\times10^{22}\\\\) টি\", \"\\\\(1.51\\\\times10^{22}\\\\) টি\"], \"ans\": 1, \"why\": \"প্রমাণ অবস্থায় \\\\(22.4\\\\ \\\\mathrm{L}\\\\)-এ থাকে \\\\(N_A\\\\) টি অণু। \\\\(N=\\\\frac{1.12}{22.4}\\\\times6.023\\\\times10^{23}=3.01\\\\times10^{22}\\\\) টি।\"}, {\"q\": \"একজন ব্যক্তি শ্বাসে \\\\(1.12\\\\ \\\\mathrm{litre}\\\\) বায়ু সেবন করে (\\\\(3.01\\\\times10^{22}\\\\) টি অণু)। \\\\(27^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রায় ঐ অণুগুলোর মোট গড় গতিশক্তি কত? [BUET 02-03]\", \"opts\": [\"\\\\(311.69\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(187.0\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(3.12\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(623.4\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 0, \"why\": \"দ্বি-পরমাণুক অণুর গড় গতিশক্তি \\\\(\\\\frac{5}{2}kT=\\\\frac{5}{2}(1.38\\\\times10^{-23})(300)=1.035\\\\times10^{-20}\\\\ \\\\mathrm{J}\\\\)। মোট \\\\(=3.01\\\\times10^{22}\\\\times1.035\\\\times10^{-20}\\\\approx311.69\\\\ \\\\mathrm{J}\\\\)।\"}, {\"q\": \"একটি পোটেনশিওমিটার তারে বিদ্যুৎ প্রবাহ নিয়ন্ত্রণ করে কোনো বিদ্যুৎ কোষের জন্য \\\\(6\\\\ \\\\mathrm{m}\\\\) দূরে নিষ্পন্দ বিন্দু পাওয়া গেল। কোষটির দু-প্রান্তের সাথে \\\\(3\\\\ \\\\Omega\\\\) রোধ যুক্ত করলে \\\\(4\\\\ \\\\mathrm{m}\\\\) দূরে নিষ্পন্দ বিন্দু পাওয়া যায়। কোষটির অভ্যন্তরীণ রোধ কত? [BUET 02-03]\", \"opts\": [\"\\\\(1.0\\\\ \\\\Omega\\\\)\", \"\\\\(2.0\\\\ \\\\Omega\\\\)\", \"\\\\(1.5\\\\ \\\\Omega\\\\)\", \"\\\\(4.5\\\\ \\\\Omega\\\\)\"], \"ans\": 2, \"why\": \"\\\\(r=\\\\left(\\\\frac{l_2}{l_1}-1\\\\right)R=\\\\left(\\\\frac{6}{4}-1\\\\right)\\\\times3=1.5\\\\ \\\\Omega\\\\)।\"}, {\"q\": \"একটি কার্নো ইঞ্জিনের দক্ষতা \\\\(\\\\frac{1}{6}\\\\)। তাপ গ্রাহকের তাপমাত্রা \\\\(65^\\\\circ\\\\mathrm{C}\\\\) কমালে দক্ষতা \\\\(\\\\frac{1}{3}\\\\) হয়। তাপ উৎস ও তাপ গ্রাহকের তাপমাত্রা যথাক্রমে কত? [BUET 02-03]\", \"opts\": [\"\\\\(325\\\\ \\\\mathrm{K}\\\\) ও \\\\(390\\\\ \\\\mathrm{K}\\\\)\", \"\\\\(390\\\\ \\\\mathrm{K}\\\\) ও \\\\(260\\\\ \\\\mathrm{K}\\\\)\", \"\\\\(390\\\\ \\\\mathrm{K}\\\\) ও \\\\(325\\\\ \\\\mathrm{K}\\\\)\", \"\\\\(455\\\\ \\\\mathrm{K}\\\\) ও \\\\(390\\\\ \\\\mathrm{K}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(1-\\\\frac{T_2}{T_1}=\\\\frac{1}{6}\\\\Rightarrow\\\\frac{T_2}{T_1}=\\\\frac{5}{6}\\\\) এবং \\\\(1-\\\\frac{T_2-65}{T_1}=\\\\frac{1}{3}\\\\)। বিয়োগ করে \\\\(\\\\frac{65}{T_1}=\\\\frac{1}{6}\\\\Rightarrow T_1=390\\\\ \\\\mathrm{K}\\\\), \\\\(T_2=\\\\frac{5}{6}\\\\times390=325\\\\ \\\\mathrm{K}\\\\)।\"}, {\"q\": \"একটি মোটর টায়ারকে \\\\(15^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রায় \\\\(2\\\\) বায়ুমণ্ডলীয় চাপে পাম্প করায় টায়ারটি হঠাৎ ফেটে গেলো। এর ফলে তাপমাত্রা কত কমে যাবে? [\\\\(\\\\gamma=1.4\\\\)] [BUET 02-03]\", \"opts\": [\"\\\\(36.74^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(51.74^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(63.5^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(25.9^\\\\circ\\\\mathrm{C}\\\\)\"], \"ans\": 1, \"why\": \"হঠাৎ প্রসারণ = রুদ্ধতাপীয়; ফেটে যাওয়ার পর চাপ \\\\(1\\\\ \\\\mathrm{atm}\\\\)। \\\\(T_2=T_1\\\\left(\\\\frac{P_2}{P_1}\\\\right)^{\\\\frac{\\\\gamma-1}{\\\\gamma}}=288\\\\left(\\\\frac{1}{2}\\\\right)^{0.286}=236.26\\\\ \\\\mathrm{K}=-36.74^\\\\circ\\\\mathrm{C}\\\\)। হ্রাস \\\\(=15-(-36.74)=51.74^\\\\circ\\\\mathrm{C}\\\\)।\"}, {\"q\": \"একটি দুই স্লিট পরীক্ষায় প্রথম সর্বনিম্নের কৌণিক অবস্থান \\\\(0.20^\\\\circ\\\\)। স্লিট দুটির মধ্যকার দূরত্ব কত? ব্যবহৃত আলোর তরঙ্গদৈর্ঘ্য \\\\(=5700\\\\ \\\\text{Å}\\\\)। [BUET 02-03]\", \"opts\": [\"\\\\(1.63\\\\times10^{-4}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(8.16\\\\times10^{-4}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(4.08\\\\times10^{-5}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(8.16\\\\times10^{-5}\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 3, \"why\": \"প্রথম সর্বনিম্নের জন্য \\\\(a\\\\sin\\\\theta=\\\\frac{\\\\lambda}{2}\\\\)। \\\\(a=\\\\frac{5700\\\\times10^{-10}}{2\\\\sin0.20^\\\\circ}=8.16\\\\times10^{-5}\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"দ্রুত গতিসম্পন্ন একটি বস্তুর দ্রুতি কত হলে বস্তুটির গতিশক্তি তার মোট শক্তির \\\\(\\\\frac{1}{5}\\\\) অংশ হবে? [BUET 02-03]\", \"opts\": [\"\\\\(0.6c\\\\)\", \"\\\\(0.8c\\\\)\", \"\\\\(0.45c\\\\)\", \"\\\\(0.5c\\\\)\"], \"ans\": 0, \"why\": \"\\\\((m-m_0)c^2=\\\\frac{1}{5}mc^2\\\\Rightarrow m_0=\\\\frac{4}{5}m\\\\Rightarrow\\\\gamma=\\\\frac{5}{4}\\\\)। \\\\(\\\\frac{v}{c}=\\\\sqrt{1-\\\\frac{1}{\\\\gamma^2}}=\\\\sqrt{1-0.64}=0.6\\\\)।\"}, {\"q\": \"\\\\(8.3\\\\times10^{7}\\\\ \\\\mathrm{m/s}\\\\) গতিতে গতিশীল একটি প্রোটনের আপেক্ষিকীয় গতিশক্তি কত? [স্থির অবস্থায় প্রোটনের ভর \\\\(=1.67265\\\\times10^{-27}\\\\ \\\\mathrm{kg}\\\\), \\\\(c=3\\\\times10^{8}\\\\ \\\\mathrm{m/s}\\\\)] [BUET 02-03]\", \"opts\": [\"\\\\(5.77\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.22\\\\times10^{-11}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(6.12\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(5.77\\\\times10^{-11}\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(E_k=m_0c^2\\\\left(\\\\frac{1}{\\\\sqrt{1-v^2/c^2}}-1\\\\right)=1.67265\\\\times10^{-27}\\\\times9\\\\times10^{16}\\\\times0.0406\\\\approx6.12\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\)। (\\\\(5.77\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\) হলো সনাতন মান।)\"}, {\"q\": \"\\\\(8.3\\\\times10^{7}\\\\ \\\\mathrm{m/s}\\\\) বেগে গতিশীল প্রোটনের ক্ষেত্রে আপেক্ষিকীয় গতিশক্তি ও সনাতন গতিশক্তির অনুপাত কত? [BUET 02-03]\", \"opts\": [\"\\\\(1.00:1\\\\)\", \"\\\\(1.06:1\\\\)\", \"\\\\(1.60:1\\\\)\", \"\\\\(0.94:1\\\\)\"], \"ans\": 1, \"why\": \"আপেক্ষিকীয় \\\\(E_k=6.12\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\), সনাতন \\\\(E_k=\\\\frac{1}{2}m_0v^2=5.77\\\\times10^{-12}\\\\ \\\\mathrm{J}\\\\)। অনুপাত \\\\(=\\\\frac{6.12}{5.77}\\\\approx1.06:1\\\\)।\"}, {\"q\": \"\\\\(r\\\\) রোধের একটি তারকে টেনে তিনগুণ লম্বা করলে, লম্বা করা তারটির রোধ কত হবে? [BUET 02-03]\", \"opts\": [\"\\\\(3r\\\\)\", \"\\\\(6r\\\\)\", \"\\\\(\\\\frac{r}{9}\\\\)\", \"\\\\(9r\\\\)\"], \"ans\": 3, \"why\": \"আয়তন ধ্রুবক থাকায় দৈর্ঘ্য \\\\(3\\\\) গুণ হলে প্রস্থচ্ছেদ \\\\(\\\\frac{1}{3}\\\\) গুণ হয়। \\\\(R=\\\\rho\\\\frac{l}{A}\\\\) অনুযায়ী রোধ \\\\(=3\\\\times3=9\\\\) গুণ, অর্থাৎ \\\\(9r\\\\)।\"}, {\"q\": \"পৃথিবী পৃষ্ঠ থেকে কোনো বস্তুকে ন্যূনতম কত বেগে মহাশূন্যের দিকে ছুড়ে মারলে বস্তুটি পৃথিবীর অভিকর্ষজ বলের আকর্ষণ কাটিয়ে উঠতে পারবে? (পৃথিবীর ব্যাসার্ধ \\\\(6.4\\\\times10^{6}\\\\ \\\\mathrm{m}\\\\)) [BUET 02-03]\", \"opts\": [\"\\\\(7.9\\\\ \\\\mathrm{km/s}\\\\)\", \"\\\\(11.2\\\\ \\\\mathrm{km/s}\\\\)\", \"\\\\(5.6\\\\ \\\\mathrm{km/s}\\\\)\", \"\\\\(22.4\\\\ \\\\mathrm{km/s}\\\\)\"], \"ans\": 1, \"why\": \"মুক্তিবেগ \\\\(v_e=\\\\sqrt{2gR}=\\\\sqrt{2\\\\times9.8\\\\times6.4\\\\times10^{6}}=11200\\\\ \\\\mathrm{m/s}=11.2\\\\ \\\\mathrm{km/s}\\\\)।\"}, {\"q\": \"একটি তাপ-যুগলের এক প্রান্ত পানি মিশ্রিত বরফে (\\\\(0^\\\\circ\\\\mathrm{C}\\\\)) রেখে অপর প্রান্ত \\\\(\\\\theta^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রায় উত্তপ্ত করলে সৃষ্ট তাপ-তড়িচ্চালক বল \\\\(E=24\\\\theta-0.04\\\\theta^2\\\\) দ্বারা প্রকাশ করা যায়। তাপ-যুগলটির নিরপেক্ষ তাপমাত্রা কত? [BUET 02-03]\", \"opts\": [\"\\\\(150^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(600^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(300^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(450^\\\\circ\\\\mathrm{C}\\\\)\"], \"ans\": 2, \"why\": \"নিরপেক্ষ তাপমাত্রায় \\\\(E\\\\) সর্বোচ্চ: \\\\(\\\\frac{dE}{d\\\\theta}=24-0.08\\\\theta=0\\\\Rightarrow\\\\theta_n=\\\\frac{24}{0.08}=300^\\\\circ\\\\mathrm{C}\\\\)।\"}, {\"q\": \"একটি তাপ-যুগলের ক্ষেত্রে তাপ-তড়িচ্চালক বল \\\\(E=24\\\\theta-0.04\\\\theta^2\\\\) (শীতল প্রান্ত \\\\(0^\\\\circ\\\\mathrm{C}\\\\)-এ)। তাপ-যুগলটির উদক্রম (উল্টন) তাপমাত্রা কত? [BUET 02-03]\", \"opts\": [\"\\\\(600^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(300^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(900^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(150^\\\\circ\\\\mathrm{C}\\\\)\"], \"ans\": 0, \"why\": \"শীতল প্রান্ত \\\\(0^\\\\circ\\\\mathrm{C}\\\\) হলে উদক্রম তাপমাত্রা \\\\(\\\\theta_i=2\\\\theta_n=2\\\\times300=600^\\\\circ\\\\mathrm{C}\\\\) (এই তাপমাত্রায় \\\\(E\\\\) আবার শূন্য হয়)।\"}, {\"q\": \"\\\\(1.5\\\\) প্রতিসরাঙ্ক বিশিষ্ট একটি কাঁচের উত্তল লেন্সের বক্রতার ব্যাসার্ধ যথাক্রমে \\\\(20\\\\ \\\\mathrm{cm}\\\\) ও \\\\(15\\\\ \\\\mathrm{cm}\\\\) হলে, \\\\(\\\\frac{4}{3}\\\\) প্রতিসরাঙ্কের পানিতে লেন্সটির ফোকাস দূরত্ব কত হবে? [BUET 02-03]\", \"opts\": [\"\\\\(17.1\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(34.3\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(137\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(68.6\\\\ \\\\mathrm{cm}\\\\)\"], \"ans\": 3, \"why\": \"পানিতে \\\\(\\\\frac{1}{f_w}=\\\\left(\\\\frac{1.5}{4/3}-1\\\\right)\\\\left(\\\\frac{1}{20}+\\\\frac{1}{15}\\\\right)=0.125\\\\times0.1167=0.01458\\\\ \\\\mathrm{cm^{-1}}\\\\)। সুতরাং \\\\(f_w\\\\approx68.6\\\\ \\\\mathrm{cm}\\\\) (বাতাসে ছিল \\\\(17.1\\\\ \\\\mathrm{cm}\\\\))।\"}, {\"q\": \"একজন নিকট দৃষ্টি সম্পন্ন ব্যক্তির নিকটতম দূরত্ব ও দূর বিন্দুর দূরত্ব যথাক্রমে \\\\(10\\\\ \\\\mathrm{cm}\\\\) ও \\\\(15\\\\ \\\\mathrm{cm}\\\\)। দূরের বস্তু স্পষ্ট দেখতে তিনি কত ক্ষমতা সম্পন্ন লেন্স ব্যবহার করবেন? [BUET 02-03]\", \"opts\": [\"\\\\(+6.67\\\\ \\\\mathrm{D}\\\\)\", \"\\\\(-6.67\\\\ \\\\mathrm{D}\\\\)\", \"\\\\(-10\\\\ \\\\mathrm{D}\\\\)\", \"\\\\(-3.33\\\\ \\\\mathrm{D}\\\\)\"], \"ans\": 1, \"why\": \"দূরের বস্তুর জন্য লেন্সের ফোকাস দূরত্ব দূর বিন্দুর সমান ও অবতল: \\\\(f=-15\\\\ \\\\mathrm{cm}=-0.15\\\\ \\\\mathrm{m}\\\\)। ক্ষমতা \\\\(P=\\\\frac{1}{f}=\\\\frac{1}{-0.15}=-6.67\\\\ \\\\mathrm{D}\\\\)।\"}, {\"q\": \"নিকট দৃষ্টি সম্পন্ন এক ব্যক্তির নিকটতম দূরত্ব \\\\(10\\\\ \\\\mathrm{cm}\\\\) ও দূর বিন্দু \\\\(15\\\\ \\\\mathrm{cm}\\\\)। দূর দর্শনের জন্য উপযুক্ত লেন্স ব্যবহার করলে তখন স্পষ্ট দর্শনের নিকটতম দূরত্ব কত হবে? [BUET 02-03]\", \"opts\": [\"\\\\(25\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(15\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(30\\\\ \\\\mathrm{cm}\\\\)\", \"\\\\(6\\\\ \\\\mathrm{cm}\\\\)\"], \"ans\": 2, \"why\": \"লেন্স \\\\(f=-15\\\\ \\\\mathrm{cm}\\\\); প্রতিবিম্ব নিকট বিন্দুতে (\\\\(v=-10\\\\ \\\\mathrm{cm}\\\\)) হতে হলে \\\\(\\\\frac{1}{u}=\\\\frac{1}{v}-\\\\frac{1}{f}\\\\) ধারায় \\\\(\\\\frac{1}{u}=\\\\frac{1}{10}-\\\\frac{1}{15}=\\\\frac{1}{30}\\\\)। সুতরাং বস্তু \\\\(30\\\\ \\\\mathrm{cm}\\\\) দূরে থাকলেই স্পষ্ট দেখা যাবে।\"}, {\"q\": \"পানিতে কানায় কানায় পূর্ণ একটি \\\\(2.5\\\\ \\\\mathrm{m}\\\\) গভীর সুইমিং পুলের তলায়, পাশের দেয়াল থেকে \\\\(2.5\\\\ \\\\mathrm{m}\\\\) দূরে একটি আলোক বাল্ব রাখা আছে। পুলের ধার (কিনারা) দিয়ে বেরিয়ে আসা রশ্মি পানির তলের সাথে কত কোণ করে বের হবে? পানির প্রতিসরাঙ্ক \\\\(\\\\mu=1.333\\\\)। [BUET 02-03]\", \"opts\": [\"\\\\(70.5^\\\\circ\\\\)\", \"\\\\(45^\\\\circ\\\\)\", \"\\\\(48.6^\\\\circ\\\\)\", \"\\\\(19.5^\\\\circ\\\\)\"], \"ans\": 3, \"why\": \"বাল্ব থেকে কিনারার বিন্দুতে আপতন কোণ \\\\(\\\\tan^{-1}(2.5/2.5)=45^\\\\circ\\\\)। স্নেলের সূত্রে \\\\(\\\\sin r=1.333\\\\sin45^\\\\circ=0.943\\\\Rightarrow r=70.5^\\\\circ\\\\) (অভিলম্বের সাথে)। তলের সাথে কোণ \\\\(=90^\\\\circ-70.5^\\\\circ=19.5^\\\\circ\\\\)।\"}, {\"q\": \"একটি বৃষ্টির ফোঁটা \\\\(30\\\\ \\\\mathrm{m/s}\\\\) প্রান্তিক বেগে বায়ুর মধ্য দিয়ে পড়ছে। পানির ঘনত্ব \\\\(10^{3}\\\\ \\\\mathrm{kg\\\\,m^{-3}}\\\\), বায়ুর ঘনত্ব \\\\(1.3\\\\ \\\\mathrm{kg\\\\,m^{-3}}\\\\) এবং বায়ুর সান্দ্রতার গুণাঙ্ক \\\\(1.8\\\\times10^{-5}\\\\) SI একক হলে, ফোঁটাটির ব্যাসার্ধ কত? [BUET 02-03]\", \"opts\": [\"\\\\(4.98\\\\times10^{-4}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(4.98\\\\times10^{-3}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(9.96\\\\times10^{-4}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(2.48\\\\times10^{-7}\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 0, \"why\": \"স্টোকসের সূত্রে \\\\(v=\\\\frac{2}{9}\\\\frac{r^2g(\\\\rho-\\\\sigma)}{\\\\eta}\\\\)। \\\\(r^2=\\\\frac{9\\\\eta v}{2g(\\\\rho-\\\\sigma)}=\\\\frac{9(1.8\\\\times10^{-5})(30)}{2(9.8)(998.7)}=2.48\\\\times10^{-7}\\\\), তাই \\\\(r\\\\approx4.98\\\\times10^{-4}\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"শব্দের তীব্রতা স্তর \\\\(1\\\\) ডেসিবেল বৃদ্ধি পেলে শব্দের তীব্রতা শতকরা কত ভাগ বৃদ্ধি পায়? [BUET 02-03]\", \"opts\": [\"\\\\(10\\\\%\\\\)\", \"\\\\(100\\\\%\\\\)\", \"\\\\(26\\\\%\\\\)\", \"\\\\(12\\\\%\\\\)\"], \"ans\": 2, \"why\": \"\\\\(\\\\Delta\\\\beta=10\\\\log\\\\frac{I_2}{I_1}=1\\\\Rightarrow\\\\frac{I_2}{I_1}=10^{0.1}=1.26\\\\)। অর্থাৎ তীব্রতা বাড়ে \\\\(0.26\\\\) অংশ \\\\(\\\\approx 26\\\\%\\\\)।\"}, {\"q\": \"\\\\(78.4\\\\ \\\\mathrm{m}\\\\) উঁচু একটি চূড়া থেকে একটি পাথরকে আনুভূমিক বরাবর ছোড়া হলো। পাথরটি চূড়ার পাদদেশ থেকে \\\\(60\\\\ \\\\mathrm{m}\\\\) দূরে ভূমিতে গিয়ে পড়ল। পাথরটি কত সময় পর ভূমিতে এসে পড়ল? [\\\\(g=9.8\\\\ \\\\mathrm{m/s^2}\\\\)] [BUET 02-03]\", \"opts\": [\"\\\\(8\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(4\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(2\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(16\\\\ \\\\mathrm{s}\\\\)\"], \"ans\": 1, \"why\": \"উল্লম্ব দিকে \\\\(h=\\\\frac{1}{2}gt^2\\\\Rightarrow t=\\\\sqrt{\\\\frac{2\\\\times78.4}{9.8}}=\\\\sqrt{16}=4\\\\ \\\\mathrm{s}\\\\)।\"}, {\"q\": \"\\\\(78.4\\\\ \\\\mathrm{m}\\\\) উঁচু চূড়া থেকে আনুভূমিকভাবে ছোড়া একটি পাথর পাদদেশ থেকে \\\\(60\\\\ \\\\mathrm{m}\\\\) দূরে \\\\(4\\\\ \\\\mathrm{s}\\\\) পরে ভূমিতে পড়ল। পাথরটি কত দ্রুতিতে ছোড়া হয়েছিল? [BUET 02-03]\", \"opts\": [\"\\\\(15\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(19.6\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(30\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(7.5\\\\ \\\\mathrm{m/s}\\\\)\"], \"ans\": 0, \"why\": \"আনুভূমিক বেগ ধ্রুবক থাকে: \\\\(u=\\\\frac{60\\\\ \\\\mathrm{m}}{4\\\\ \\\\mathrm{s}}=15\\\\ \\\\mathrm{m/s}\\\\)।\"}, {\"q\": \"ফাঁকা মাঠে অনুষ্ঠিত কনসার্টে ব্যবহৃত একটি লাউড স্পিকার \\\\(250\\\\ \\\\mathrm{W}\\\\) শক্তি উৎপন্ন করে। স্পিকার হতে \\\\(20\\\\ \\\\mathrm{m}\\\\) দূরে শব্দের তীব্রতা কত হবে? [BUET 02-03]\", \"opts\": [\"\\\\(0.199\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.0221\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.0497\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.0995\\\\ \\\\mathrm{W/m^2}\\\\)\"], \"ans\": 2, \"why\": \"\\\\(I=\\\\frac{P}{4\\\\pi r^2}=\\\\frac{250}{4\\\\pi(20)^2}=\\\\frac{250}{5026}\\\\approx0.0497\\\\ \\\\mathrm{W/m^2}\\\\)।\"}, {\"q\": \"\\\\(250\\\\ \\\\mathrm{W}\\\\) ক্ষমতার একটি লাউড স্পিকার হতে \\\\(30\\\\ \\\\mathrm{m}\\\\) দূরে শব্দের তীব্রতা কত হবে? [BUET 02-03]\", \"opts\": [\"\\\\(0.0497\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.0221\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.0332\\\\ \\\\mathrm{W/m^2}\\\\)\", \"\\\\(0.00884\\\\ \\\\mathrm{W/m^2}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(I=\\\\frac{P}{4\\\\pi r^2}=\\\\frac{250}{4\\\\pi(30)^2}=\\\\frac{250}{11310}\\\\approx0.0221\\\\ \\\\mathrm{W/m^2}\\\\)।\"}, {\"q\": \"একটি লাউড স্পিকার থেকে দূরত্ব \\\\(20\\\\ \\\\mathrm{m}\\\\) থেকে \\\\(30\\\\ \\\\mathrm{m}\\\\)-এ গেলে শব্দের তীব্রতা স্তর ডেসিবেলে কতটুকু হ্রাস পাবে? [BUET 02-03]\", \"opts\": [\"\\\\(1.76\\\\ \\\\mathrm{dB}\\\\)\", \"\\\\(5.0\\\\ \\\\mathrm{dB}\\\\)\", \"\\\\(3.52\\\\ \\\\mathrm{dB}\\\\)\", \"\\\\(7.04\\\\ \\\\mathrm{dB}\\\\)\"], \"ans\": 2, \"why\": \"তীব্রতা দূরত্বের বর্গের ব্যস্তানুপাতিক: \\\\(\\\\Delta\\\\beta=10\\\\log\\\\left(\\\\frac{30}{20}\\\\right)^2=20\\\\log1.5\\\\approx3.52\\\\ \\\\mathrm{dB}\\\\)।\"}, {\"q\": \"\\\\(40\\\\ \\\\mathrm{cm}\\\\) দীর্ঘ এবং \\\\(4\\\\ \\\\mathrm{cm}\\\\) ব্যাসার্ধযুক্ত \\\\(200\\\\) পাকের একটি সলিনয়েডের আবেশ গুণাঙ্ক (স্বাবেশ গুণাঙ্ক) নির্ণয় কর। (\\\\(\\\\mu_r=1\\\\)) [BUET 02-03]\", \"opts\": [\"\\\\(6.32\\\\times10^{-3}\\\\ \\\\mathrm{H}\\\\)\", \"\\\\(6.32\\\\times10^{-4}\\\\ \\\\mathrm{H}\\\\)\", \"\\\\(3.16\\\\times10^{-4}\\\\ \\\\mathrm{H}\\\\)\", \"\\\\(1.26\\\\times10^{-3}\\\\ \\\\mathrm{H}\\\\)\"], \"ans\": 1, \"why\": \"\\\\(L=\\\\mu_0 n^2 A l=4\\\\pi\\\\times10^{-7}\\\\times\\\\left(\\\\frac{200}{0.4}\\\\right)^2\\\\times\\\\pi(0.04)^2\\\\times0.4\\\\approx6.32\\\\times10^{-4}\\\\ \\\\mathrm{H}\\\\)।\"}]"}, "adm-buet-2003-04": {"title": "বহুনির্বাচনি পরীক্ষা — বুয়েট ২০০৩-০৪", "chapter": "Admission", "level": "বুয়েট", "minutes": 23, "qjson": "[{\"q\": \"মঙ্গল গ্রহের ভর পৃথিবীর ভরের \\\\(0.11\\\\) গুণ এবং এর ব্যাসার্ধ পৃথিবীর ব্যাসার্ধের \\\\(0.532\\\\) গুণ। মঙ্গল গ্রহের ভূ-পৃষ্ঠ থেকে একটি মহাশূন্যযানকে ন্যূনতম কত বেগে উৎক্ষেপণ করলে মহাশূন্যযানটি মঙ্গল গ্রহের মধ্যাকর্ষণ বলের বাইরে চলে যেতে পারবে? [পৃথিবীর ভর \\\\(5.975\\\\times 10^{24}\\\\ \\\\mathrm{kg}\\\\), পৃথিবীর ব্যাসার্ধ \\\\(=6.371\\\\times 10^{6}\\\\ \\\\mathrm{m}\\\\), \\\\(G=6.673\\\\times 10^{-11}\\\\ \\\\mathrm{N\\\\,m^{2}\\\\,kg^{-2}}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(3.60\\\\ \\\\mathrm{km\\\\,s^{-1}}\\\\)\", \"\\\\(7.19\\\\ \\\\mathrm{km\\\\,s^{-1}}\\\\)\", \"\\\\(11.2\\\\ \\\\mathrm{km\\\\,s^{-1}}\\\\)\", \"\\\\(5.09\\\\ \\\\mathrm{km\\\\,s^{-1}}\\\\)\"], \"ans\": 3, \"why\": \"মঙ্গলে মুক্তিবেগ \\\\(v_e=\\\\sqrt{\\\\frac{2GM_m}{R_m}}=\\\\sqrt{\\\\frac{2\\\\times 6.673\\\\times 10^{-11}\\\\times 0.11\\\\times 5.975\\\\times 10^{24}}{0.532\\\\times 6.371\\\\times 10^{6}}}\\\\approx 5087\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)।\"}, {\"q\": \"\\\\(130\\\\ \\\\mathrm{cm}\\\\) দীর্ঘ এবং \\\\(1.1\\\\ \\\\mathrm{mm}\\\\) ব্যাসের একটি ইস্পাতের তারকে \\\\(830^\\\\circ\\\\mathrm{C}\\\\) তাপমাত্রায় উত্তপ্ত করে তারের দুই প্রান্ত দুটি দৃঢ় বন্ধনীর সাথে এরূপ আটকিয়ে দেয়া হলো যেন তারটি দুপাশে টানা অবস্থায় থাকে। তারটি ঠান্ডা হয়ে \\\\(20^\\\\circ\\\\mathrm{C}\\\\)-এ নেমে আসলে তারে কি পরিমাণ টান সৃষ্টি হবে? [ইস্পাতের ইয়ং গুণাঙ্ক, \\\\(Y=200\\\\times 10^{9}\\\\ \\\\mathrm{N\\\\,m^{-2}}\\\\), তাপীয় প্রসারাঙ্ক, \\\\(\\\\alpha=11\\\\times 10^{-6}\\\\ /^\\\\circ\\\\mathrm{C}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(1693.5\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(846.7\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(3387\\\\ \\\\mathrm{N}\\\\)\", \"\\\\(423.4\\\\ \\\\mathrm{N}\\\\)\"], \"ans\": 0, \"why\": \"সংকোচন বাধাপ্রাপ্ত হলে টান \\\\(F=YA\\\\alpha\\\\Delta\\\\theta=200\\\\times 10^{9}\\\\times\\\\pi (0.55\\\\times 10^{-3})^2\\\\times 11\\\\times 10^{-6}\\\\times (830-20)\\\\approx 1693.5\\\\ \\\\mathrm{N}\\\\)।\"}, {\"q\": \"একটি স্থির লিফটের মধ্যে রাখা একটি সরল দোলকের দোলনকাল \\\\(T\\\\)। যদি লিফটটি উপরের দিকে \\\\(\\\\frac{g}{4}\\\\) ত্বরণ নিয়ে উঠে, তাহলে দোলকটির দোলনকাল কত হবে? [BUET 03-04]\", \"opts\": [\"\\\\(\\\\frac{T}{2}\\\\)\", \"\\\\(\\\\frac{4}{5}T\\\\)\", \"\\\\(\\\\frac{\\\\sqrt{5}}{2}T\\\\)\", \"\\\\(\\\\frac{2}{\\\\sqrt{5}}T\\\\)\"], \"ans\": 3, \"why\": \"লিফটে কার্যকর ত্বরণ \\\\(g_2=g+\\\\frac{g}{4}=\\\\frac{5g}{4}\\\\); \\\\(T\\\\propto\\\\frac{1}{\\\\sqrt{g}}\\\\) বলে \\\\(T_2=T\\\\sqrt{\\\\frac{g}{g_2}}=\\\\frac{2}{\\\\sqrt{5}}T\\\\)।\"}, {\"q\": \"একটি কার্নো ইঞ্জিনের তাপ উৎস ও তাপ গ্রাহকের তাপমাত্রা যথাক্রমে \\\\(500\\\\ \\\\mathrm{K}\\\\) ও \\\\(375\\\\ \\\\mathrm{K}\\\\)। ইঞ্জিনটি প্রতি চক্রে \\\\(252\\\\times 10^{4}\\\\ \\\\mathrm{J}\\\\) তাপ শোষণ করে। ইঞ্জিনের দক্ষতা কত? [BUET 03-04]\", \"opts\": [\"\\\\(75\\\\%\\\\)\", \"\\\\(33.3\\\\%\\\\)\", \"\\\\(25\\\\%\\\\)\", \"\\\\(20\\\\%\\\\)\"], \"ans\": 2, \"why\": \"\\\\(\\\\eta=1-\\\\frac{T_2}{T_1}=1-\\\\frac{375}{500}=\\\\frac{1}{4}=25\\\\%\\\\)।\"}, {\"q\": \"একটি কার্নো ইঞ্জিনের তাপ উৎস ও তাপ গ্রাহকের তাপমাত্রা যথাক্রমে \\\\(500\\\\ \\\\mathrm{K}\\\\) ও \\\\(375\\\\ \\\\mathrm{K}\\\\)। ইঞ্জিনটি প্রতি চক্রে \\\\(252\\\\times 10^{4}\\\\ \\\\mathrm{J}\\\\) তাপ শোষণ করে। প্রতিচক্রে কাজের পরিমাণ কত? [BUET 03-04]\", \"opts\": [\"\\\\(6.3\\\\times 10^{5}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.89\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(2.52\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(6.3\\\\times 10^{4}\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(\\\\eta=\\\\frac{W}{Q_1}\\\\Rightarrow W=0.25\\\\times 252\\\\times 10^{4}=6.3\\\\times 10^{5}\\\\ \\\\mathrm{J}\\\\)।\"}, {\"q\": \"একটি কার্নো ইঞ্জিনের তাপ উৎস ও তাপ গ্রাহকের তাপমাত্রা যথাক্রমে \\\\(500\\\\ \\\\mathrm{K}\\\\) ও \\\\(375\\\\ \\\\mathrm{K}\\\\)। ইঞ্জিনটি প্রতি চক্রে \\\\(252\\\\times 10^{4}\\\\ \\\\mathrm{J}\\\\) তাপ শোষণ করে। প্রতিচক্রে বর্জিত তাপের পরিমাণ কত? [BUET 03-04]\", \"opts\": [\"\\\\(2.52\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.26\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(6.3\\\\times 10^{5}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.89\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(Q_2=Q_1-W=252\\\\times 10^{4}-6.3\\\\times 10^{5}=1.89\\\\times 10^{6}\\\\ \\\\mathrm{J}\\\\)।\"}, {\"q\": \"একটি সরু রেখাছিদ্র দ্বারা ফ্রনহফার অপবর্তন সৃষ্টির জন্য লেন্স হতে \\\\(2\\\\ \\\\mathrm{m}\\\\) দূরে পর্দা রাখা হলো। রেখা ছিদ্রের প্রস্থ \\\\(0.2\\\\ \\\\mathrm{mm}\\\\) হলে দেখা যায় যে কেন্দ্রীয় উজ্জ্বল বিন্দুর উভয় পার্শ্বে \\\\(5\\\\ \\\\mathrm{mm}\\\\) দূরত্বে অবম বিন্দু গঠিত হয়। আপতিত আলোর তরঙ্গদৈর্ঘ্য নির্ণয় করো। [BUET 03-04]\", \"opts\": [\"\\\\(5\\\\times 10^{-7}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(2.5\\\\times 10^{-7}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(1\\\\times 10^{-6}\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(5\\\\times 10^{-6}\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(\\\\tan\\\\theta=\\\\frac{5\\\\times 10^{-3}}{2}\\\\Rightarrow \\\\sin\\\\theta\\\\approx 2.5\\\\times 10^{-3}\\\\); প্রথম অবমের শর্ত \\\\(a\\\\sin\\\\theta=\\\\lambda\\\\) থেকে \\\\(\\\\lambda=0.2\\\\times 10^{-3}\\\\times 2.5\\\\times 10^{-3}=5\\\\times 10^{-7}\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"\\\\(1.67\\\\times 10^{-27}\\\\ \\\\mathrm{kg}\\\\) স্থিতি ভরের একটি প্রোটনের ভর দ্বিগুণ হতে হলে কত দ্রুতির প্রয়োজন হবে? [\\\\(c=3\\\\times 10^{8}\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(0.5c\\\\)\", \"\\\\(0.707c\\\\)\", \"\\\\(0.866c\\\\)\", \"\\\\(0.943c\\\\)\"], \"ans\": 2, \"why\": \"\\\\(m=\\\\frac{m_0}{\\\\sqrt{1-v^2/c^2}}\\\\Rightarrow 2m_0=\\\\frac{m_0}{\\\\sqrt{1-v^2/c^2}}\\\\Rightarrow 1-\\\\frac{v^2}{c^2}=\\\\frac{1}{4}\\\\Rightarrow v=\\\\frac{\\\\sqrt{3}}{2}c\\\\approx 0.866c\\\\)।\"}, {\"q\": \"\\\\(1.67\\\\times 10^{-27}\\\\ \\\\mathrm{kg}\\\\) স্থিতি ভরের একটি প্রোটনের ভর দ্বিগুণ করতে যে গতিশক্তি প্রয়োজন হবে তা কত? [\\\\(c=3\\\\times 10^{8}\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(7.5\\\\times 10^{-11}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(4.5\\\\times 10^{-10}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(3.01\\\\times 10^{-10}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.50\\\\times 10^{-10}\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(E_k=(m-m_0)c^2=(2m_0-m_0)c^2=m_0c^2=1.67\\\\times 10^{-27}\\\\times 9\\\\times 10^{16}=1.503\\\\times 10^{-10}\\\\ \\\\mathrm{J}\\\\)।\"}, {\"q\": \"কোনো ধাতুর পৃষ্ঠে আলোকরশ্মি আপতিত হওয়ায় নিঃসৃত ইলেকট্রন সম্পূর্ণরূপে থামাতে \\\\(3\\\\ \\\\mathrm{V}\\\\) বিরতি বিভবের প্রয়োজন হয়। উক্ত ধাতুর আলোক তড়িৎ ক্রিয়া \\\\(6\\\\times 10^{14}\\\\ \\\\mathrm{Hz}\\\\) কম্পাঙ্কের আলোকরশ্মি দ্বারা সূচিত হয়। আপতিত আলোকরশ্মির কম্পাঙ্ক কত? [\\\\(h=6.63\\\\times 10^{-34}\\\\ \\\\mathrm{Js}\\\\), \\\\(e=1.6\\\\times 10^{-19}\\\\ \\\\mathrm{C}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(1.32\\\\times 10^{15}\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(6\\\\times 10^{14}\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(9.6\\\\times 10^{14}\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(7.24\\\\times 10^{14}\\\\ \\\\mathrm{Hz}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(hf=hf_0+eV\\\\Rightarrow f=f_0+\\\\frac{eV}{h}=6\\\\times 10^{14}+\\\\frac{1.6\\\\times 10^{-19}\\\\times 3}{6.63\\\\times 10^{-34}}\\\\approx 1.32\\\\times 10^{15}\\\\ \\\\mathrm{Hz}\\\\)।\"}, {\"q\": \"কোনো ধাতুর পৃষ্ঠে আলোকরশ্মি আপতিত হওয়ায় নিঃসৃত ইলেকট্রন সম্পূর্ণরূপে থামাতে \\\\(3\\\\ \\\\mathrm{V}\\\\) বিরতি বিভবের প্রয়োজন হয়। উক্ত ধাতুর আলোক তড়িৎ ক্রিয়া \\\\(6\\\\times 10^{14}\\\\ \\\\mathrm{Hz}\\\\) কম্পাঙ্কের আলোকরশ্মি দ্বারা সূচিত হয়। ধাতুর কার্য অপেক্ষক কত? [\\\\(h=6.63\\\\times 10^{-34}\\\\ \\\\mathrm{Js}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(3.98\\\\times 10^{-19}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(1.99\\\\times 10^{-19}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(4.8\\\\times 10^{-19}\\\\ \\\\mathrm{J}\\\\)\", \"\\\\(7.96\\\\times 10^{-19}\\\\ \\\\mathrm{J}\\\\)\"], \"ans\": 0, \"why\": \"\\\\(W_0=hf_0=6.63\\\\times 10^{-34}\\\\times 6\\\\times 10^{14}=3.98\\\\times 10^{-19}\\\\ \\\\mathrm{J}\\\\) (প্রায় \\\\(2.49\\\\ \\\\mathrm{eV}\\\\))।\"}, {\"q\": \"একটি ইলেকট্রন \\\\(10^{7}\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\) গতিবেগ নিয়ে চলছে। এর গতিশক্তি ইলেকট্রন-ভোল্টে নির্ণয় করো। [ইলেকট্রনের ভর \\\\(m=9.1\\\\times 10^{-31}\\\\ \\\\mathrm{kg}\\\\), ইলেকট্রনের চার্জ \\\\(e=1.6\\\\times 10^{-19}\\\\ \\\\mathrm{C}\\\\), \\\\(c=3\\\\times 10^{8}\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\)] [BUET 03-04]\", \"opts\": [\"\\\\(569\\\\ \\\\mathrm{eV}\\\\)\", \"\\\\(2557\\\\ \\\\mathrm{eV}\\\\)\", \"\\\\(28.5\\\\ \\\\mathrm{eV}\\\\)\", \"\\\\(284.6\\\\ \\\\mathrm{eV}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(E_k=m_0c^2\\\\left[\\\\frac{1}{\\\\sqrt{1-v^2/c^2}}-1\\\\right]=4.55\\\\times 10^{-17}\\\\ \\\\mathrm{J}\\\\); eV-এ \\\\(\\\\frac{4.55\\\\times 10^{-17}}{1.6\\\\times 10^{-19}}\\\\approx 284.6\\\\ \\\\mathrm{eV}\\\\)।\"}, {\"q\": \"এক গ্রাম রেডিয়াম \\\\(5\\\\) বৎসর \\\\(\\\\alpha\\\\)-কণা বিকিরণের ফলে \\\\(2.1\\\\ \\\\mathrm{mg}\\\\) কমে যায়। রেডিয়ামের অর্ধায়ু বের করো। [BUET 03-04]\", \"opts\": [\"\\\\(3297\\\\) বছর\", \"\\\\(165\\\\) বছর\", \"\\\\(824\\\\) বছর\", \"\\\\(1649\\\\) বছর\"], \"ans\": 3, \"why\": \"\\\\(m=m_0e^{-\\\\lambda t}\\\\): \\\\((1-2.1\\\\times 10^{-3})=e^{-5\\\\lambda}\\\\Rightarrow \\\\lambda=4.20\\\\times 10^{-4}\\\\ \\\\mathrm{yr^{-1}}\\\\); \\\\(T_{1/2}=\\\\frac{\\\\ln 2}{\\\\lambda}\\\\approx 1649\\\\) বছর।\"}, {\"q\": \"প্রতি ঘন্টায় \\\\(3600\\\\ \\\\mathrm{m}\\\\) বেগে সাঁতারে সক্ষম একজন সাঁতারু একটি নদীর অপর পাড়ের বিপরীত বিন্দুতে যেতে ইচ্ছুক। স্রোতের বেগ \\\\(1800\\\\ \\\\mathrm{m\\\\,h^{-1}}\\\\); নদীর প্রস্থ \\\\(240\\\\ \\\\mathrm{m}\\\\)। সে কোন দিক বরাবর (স্রোতের দিকের সাথে কত কোণে) সাঁতার দেবে? [BUET 03-04]\", \"opts\": [\"\\\\(60^\\\\circ\\\\)\", \"\\\\(90^\\\\circ\\\\)\", \"\\\\(120^\\\\circ\\\\)\", \"\\\\(150^\\\\circ\\\\)\"], \"ans\": 2, \"why\": \"লব্ধি বেগ পাড়ের লম্ব বরাবর হতে হলে সাঁতারুর স্রোতমুখী উপাংশ স্রোতকে কাটাতে হবে: \\\\(\\\\cos\\\\alpha=-\\\\frac{u}{v}=-\\\\frac{1800}{3600}=-0.5\\\\Rightarrow \\\\alpha=120^\\\\circ\\\\)।\"}, {\"q\": \"প্রতি ঘন্টায় \\\\(3600\\\\ \\\\mathrm{m}\\\\) বেগে সাঁতারে সক্ষম একজন সাঁতারু একটি নদীর অপর পাড়ের বিপরীত বিন্দুতে যেতে ইচ্ছুক। স্রোতের বেগ \\\\(1800\\\\ \\\\mathrm{m\\\\,h^{-1}}\\\\); নদীর প্রস্থ \\\\(240\\\\ \\\\mathrm{m}\\\\)। সেই বিন্দুতে যেতে সে কত সময় নেবে? [BUET 03-04]\", \"opts\": [\"\\\\(480\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(138.6\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(240\\\\ \\\\mathrm{s}\\\\)\", \"\\\\(277.1\\\\ \\\\mathrm{s}\\\\)\"], \"ans\": 3, \"why\": \"সাঁতারুর বেগ \\\\(v=1\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\), স্রোত \\\\(u=0.5\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\); পাড়ের লম্ব বরাবর কার্যকর বেগ \\\\(\\\\sqrt{v^2-u^2}=0.866\\\\ \\\\mathrm{m\\\\,s^{-1}}\\\\); সময় \\\\(t=\\\\frac{240}{0.866}\\\\approx 277.1\\\\ \\\\mathrm{s}\\\\)।\"}, {\"q\": \"একটি আবদ্ধ পাত্রে \\\\(20^\\\\circ\\\\mathrm{C}\\\\) উষ্ণতায় আর্দ্র বায়ু আছে যখন আপেক্ষিক আর্দ্রতা \\\\(30\\\\%\\\\)। যদি উষ্ণতা \\\\(10^\\\\circ\\\\mathrm{C}\\\\)-এ নামিয়ে আনা হয় তখন আপেক্ষিক আর্দ্রতা কত হবে? দেওয়া আছে, \\\\(20^\\\\circ\\\\mathrm{C}\\\\) এবং \\\\(10^\\\\circ\\\\mathrm{C}\\\\)-এ সম্পৃক্ত বাষ্পচাপ যথাক্রমে \\\\(17.5\\\\ \\\\mathrm{mm}\\\\) পারদ স্তম্ভের চাপ এবং \\\\(9.2\\\\ \\\\mathrm{mm}\\\\) পারদ স্তম্ভের চাপ। [BUET 03-04]\", \"opts\": [\"\\\\(30\\\\%\\\\)\", \"\\\\(44.1\\\\%\\\\)\", \"\\\\(55.1\\\\%\\\\)\", \"\\\\(57.1\\\\%\\\\)\"], \"ans\": 2, \"why\": \"বর্তমান বাষ্পচাপ \\\\(f_1=0.30\\\\times 17.5=5.25\\\\ \\\\mathrm{mm\\\\,Hg}\\\\); আবদ্ধ পাত্রে \\\\(f\\\\propto T\\\\) (কেলভিন) বলে \\\\(f_2=5.25\\\\times\\\\frac{283}{293}=5.07\\\\); নতুন আপেক্ষিক আর্দ্রতা \\\\(=\\\\frac{5.07}{9.2}\\\\times 100\\\\%\\\\approx 55.1\\\\%\\\\)।\"}, {\"q\": \"একটি ট্যানজেন্ট গ্যালভানোমিটারের মধ্য দিয়ে \\\\(5\\\\ \\\\mathrm{amp}\\\\) বিদ্যুৎ প্রবাহিত করলে এর কাঁটা \\\\(30^\\\\circ\\\\) কোণে বিক্ষেপিত হয়। গ্যালভানোমিটার দিয়ে কত অ্যাম্পিয়ার বিদ্যুৎ প্রবাহিত করলে কাঁটা \\\\(45^\\\\circ\\\\) কোণে বিক্ষেপিত হবে? [BUET 03-04]\", \"opts\": [\"\\\\(10\\\\ \\\\mathrm{A}\\\\)\", \"\\\\(2.89\\\\ \\\\mathrm{A}\\\\)\", \"\\\\(7.5\\\\ \\\\mathrm{A}\\\\)\", \"\\\\(8.66\\\\ \\\\mathrm{A}\\\\)\"], \"ans\": 3, \"why\": \"ট্যানজেন্ট সূত্রে \\\\(I\\\\propto\\\\tan\\\\theta\\\\); \\\\(\\\\frac{I_1}{I_2}=\\\\frac{\\\\tan\\\\theta_1}{\\\\tan\\\\theta_2}\\\\Rightarrow I_2=5\\\\times\\\\frac{\\\\tan 45^\\\\circ}{\\\\tan 30^\\\\circ}=8.66\\\\ \\\\mathrm{A}\\\\)।\"}, {\"q\": \"সাধারণ বিদ্যুৎ সরবরাহ লাইনে সংযুক্ত একটি বৈদ্যুতিক চুল্লির উপাদানের অবিচল তাপমাত্রা \\\\(800^\\\\circ\\\\mathrm{C}\\\\)। যদি বিদ্যুৎ সরবরাহ (ক্ষমতা) \\\\(20\\\\%\\\\) বৃদ্ধি দেখানো হয়, তাহলে উপাদানের অবিচল তাপমাত্রা বের করো। উপাদানকে কৃষ্ণকায় বস্তু হিসাবে ধরো। (\\\\(\\\\sigma=5.72\\\\times 10^{-8}\\\\ \\\\mathrm{W\\\\,m^{-2}\\\\,K^{-4}}\\\\)) [BUET 03-04]\", \"opts\": [\"\\\\(902^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(960^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(840^\\\\circ\\\\mathrm{C}\\\\)\", \"\\\\(850^\\\\circ\\\\mathrm{C}\\\\)\"], \"ans\": 3, \"why\": \"অবিচল অবস্থায় সরবরাহকৃত ক্ষমতা = বিকিরিত ক্ষমতা \\\\(\\\\propto T^4\\\\); \\\\(T_1=800+273=1073\\\\ \\\\mathrm{K}\\\\); \\\\(T_2=1073\\\\times (1.2)^{1/4}=1123\\\\ \\\\mathrm{K}\\\\approx 850^\\\\circ\\\\mathrm{C}\\\\)।\"}, {\"q\": \"স্বাভাবিক চাপ ও তাপমাত্রায় বাতাসে শব্দের বেগ \\\\(330\\\\ \\\\mathrm{m/s}\\\\) হলে, হাইড্রোজেনে শব্দের বেগ কত? (এক লিটার হাইড্রোজেনের ভর \\\\(0.896\\\\times10^{-3}\\\\ \\\\mathrm{kg}\\\\) ও এক লিটার বাতাসের ভর \\\\(1.293\\\\times10^{-3}\\\\ \\\\mathrm{kg}\\\\)) [BUET 03-04]\", \"opts\": [\"\\\\(275\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(396\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(476\\\\ \\\\mathrm{m/s}\\\\)\", \"\\\\(330\\\\ \\\\mathrm{m/s}\\\\)\"], \"ans\": 1, \"why\": \"একই চাপ ও তাপমাত্রায় \\\\(v\\\\propto \\\\frac{1}{\\\\sqrt{\\\\rho}}\\\\)। তাই \\\\(v_{H_2}=330\\\\times\\\\sqrt{\\\\frac{1.293}{0.896}}=330\\\\times1.20\\\\approx 396\\\\ \\\\mathrm{m/s}\\\\)।\"}, {\"q\": \"দুটি সুর-শলাকা A এবং B-কে একই সাথে কাঁপালে প্রতি সেকেন্ডে 5টি স্বরকম্পের সৃষ্টি হয়। A-এর উপর কিছুটা ওজন (মোম) দিলে স্বরকম্পের সংখ্যা কমে যায়। B-এর কম্পাঙ্ক প্রতি সেকেন্ডে 256 হলে, A-এর কম্পাঙ্ক কত? [BUET 03-04]\", \"opts\": [\"\\\\(251\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(256\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(261\\\\ \\\\mathrm{Hz}\\\\)\", \"\\\\(246\\\\ \\\\mathrm{Hz}\\\\)\"], \"ans\": 2, \"why\": \"মোম দিলে A-এর কম্পাঙ্ক কমে; তবু বিট কমেছে মানে A-এর কম্পাঙ্ক B-এর দিকে এগিয়েছে, অর্থাৎ \\\\(f_A>f_B\\\\)। সুতরাং \\\\(f_A=256+5=261\\\\ \\\\mathrm{Hz}\\\\)।\"}, {\"q\": \"\\\\(2.0\\\\ \\\\mathrm{cm}\\\\) চওড়া এবং \\\\(1.0\\\\ \\\\mathrm{mm}\\\\) পুরু একটি তামার পাতকে চুম্বক ক্ষেত্রে রাখা হলো। ক্ষেত্রের প্রাবল্য \\\\(B=1.5\\\\ \\\\mathrm{Wb/m^2}\\\\) পাতের তলের সাথে \\\\(90^\\\\circ\\\\) কোণ করে আছে। পাতের ভিতর দিয়ে \\\\(200\\\\ \\\\mathrm{A}\\\\) বিদ্যুৎ প্রবাহিত করলে Hall বিভব \\\\(V_H\\\\) কত হবে? (তামার পরিবাহী ইলেকট্রন সংখ্যা ঘনত্ব \\\\(n=8.4\\\\times10^{22}\\\\ \\\\mathrm{cm^{-3}}\\\\)) [BUET 03-04]\", \"opts\": [\"\\\\(2.23\\\\times10^{-4}\\\\ \\\\mathrm{V}\\\\)\", \"\\\\(2.23\\\\times10^{-6}\\\\ \\\\mathrm{V}\\\\)\", \"\\\\(4.46\\\\times10^{-5}\\\\ \\\\mathrm{V}\\\\)\", \"\\\\(2.23\\\\times10^{-5}\\\\ \\\\mathrm{V}\\\\)\"], \"ans\": 3, \"why\": \"\\\\(V_H=\\\\frac{IB}{net}=\\\\frac{200\\\\times1.5}{(8.4\\\\times10^{28})(1.6\\\\times10^{-19})(1.0\\\\times10^{-3})}\\\\approx2.23\\\\times10^{-5}\\\\ \\\\mathrm{V}\\\\) (এখানে \\\\(t\\\\) = পাতের পুরুত্ব)।\"}, {\"q\": \"একটি টেলিস্কোপের অভিলক্ষ্য ও অভিনেত্রের ফোকাস দূরত্ব যথাক্রমে \\\\(0.50\\\\ \\\\mathrm{m}\\\\) ও \\\\(0.05\\\\ \\\\mathrm{m}\\\\)। স্পষ্ট দর্শনের ন্যূনতম দূরত্ব \\\\(0.25\\\\ \\\\mathrm{m}\\\\)। অভিলক্ষ্য থেকে \\\\(2.0\\\\ \\\\mathrm{m}\\\\) দূরের একটি স্কেলের উপর টেলিস্কোপকে স্পষ্ট দর্শনের জন্য ফোকাস করা হলো। অভিলক্ষ্য ও অভিনেত্রের মধ্যবর্তী দূরত্ব কত? [BUET 03-04]\", \"opts\": [\"\\\\(0.708\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(2.55\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(0.55\\\\ \\\\mathrm{m}\\\\)\", \"\\\\(0.625\\\\ \\\\mathrm{m}\\\\)\"], \"ans\": 0, \"why\": \"অভিলক্ষ্য: \\\\(\\\\frac{1}{v}=\\\\frac{1}{0.50}-\\\\frac{1}{2.0}\\\\Rightarrow v=0.667\\\\ \\\\mathrm{m}\\\\)। অভিনেত্রে শেষ প্রতিবিম্ব \\\\(0.25\\\\ \\\\mathrm{m}\\\\)-এ: \\\\(\\\\frac{1}{u_e}=\\\\frac{1}{0.05}+\\\\frac{1}{0.25}=24\\\\Rightarrow u_e=0.0417\\\\ \\\\mathrm{m}\\\\)। দূরত্ব \\\\(=0.667+0.0417\\\\approx0.708\\\\ \\\\mathrm{m}\\\\)।\"}, {\"q\": \"একটি টেলিস্কোপের অভিলক্ষ্য ও অভিনেত্রের ফোকাস দূরত্ব যথাক্রমে \\\\(0.50\\\\ \\\\mathrm{m}\\\\) ও \\\\(0.05\\\\ \\\\mathrm{m}\\\\)। স্পষ্ট দর্শনের ন্যূনতম দূরত্ব \\\\(0.25\\\\ \\\\mathrm{m}\\\\)। অভিলক্ষ্য থেকে \\\\(2.0\\\\ \\\\mathrm{m}\\\\) দূরের স্কেলের উপর ফোকাস করা অবস্থায় টেলিস্কোপটির বিবর্ধন কত? [BUET 03-04]\", \"opts\": [\"\\\\(10\\\\)\", \"\\\\(3\\\\)\", \"\\\\(2\\\\)\", \"\\\\(6\\\\)\"], \"ans\": 2, \"why\": \"অভিলক্ষ্যের বিবর্ধন \\\\(m_o=\\\\frac{v}{u}=\\\\frac{0.667}{2.0}=\\\\frac{1}{3}\\\\); অভিনেত্রের কৌণিক বিবর্ধন \\\\(m_e=1+\\\\frac{D}{f_e}=1+\\\\frac{0.25}{0.05}=6\\\\)। মোট বিবর্ধন \\\\(=\\\\frac{1}{3}\\\\times6=2\\\\)।\"}]"}};
